INSERT INTO wiki_chunks (id,page_path,ordinal,heading_path,text,token_count,source_refs_json,content_sha) SELECT json_extract(value,'$[0]'),json_extract(value,'$[1]'),json_extract(value,'$[2]'),json_extract(value,'$[3]'),json_extract(value,'$[4]'),json_extract(value,'$[5]'),json_extract(value,'$[6]'),json_extract(value,'$[7]') FROM json_each('[["chunk_51b8f1914156ff71873b78ab","wiki/sources/celex-32017d2075-de-txt.md",0,"Seite 1","14.11.2017 DE Amtsblatt der Europäischen Union L 295/69\r\n\r\nDELEGIERTER BESCHLUSS (EU) 2017/2075 DER KOMMISSION\r\n\r\nvom 4. September 2017\r\n\r\nzur Ersetzung des Anhangs VII der Richtlinie 2012/34/EU des Europäischen Parlaments und des\r\n\r\nRates zur Schaffung eines einheitlichen europäischen Eisenbahnraums\r\n\r\n(Text von Bedeutung für den EWR)\r\n\r\nDIE EUROPÄISCHE KOMMISSION —\r\n\r\ngestützt auf den Vertrag über die Arbeitsweise der Europäischen Union,\r\n\r\ngestützt auf die Richtlinie 2012/34/EU des Europäischen Parlaments und des Rates vom 21. November 2012 zur\r\n\r\nSchaffung eines einheitlichen europäischen Eisenbahnraums (1), insbesondere auf Artikel 43 Absatz 2,\r\n\r\nin Erwägung nachstehender Gründe:\r\n\r\n(1) Die Kapazitätszuweisung sollte auf transparente Weise erfolgen, und gleichzeitig sollten die Effizienz des\r\n\r\nZuweisungsverfahrens sowie die betrieblichen Belange aller an der Nutzung und Instandhaltung der Schieneninf\r\n\r\nrastruktur beteiligten Interessengruppen berücksichtigt werden.\r\n\r\n(2) Im Rahmen der Zuweisung von Infrastrukturkapazität sollten die Antragsteller die Möglichkeit erhalten, die\r\n\r\nEinbeziehung von Kapazität in den jährlichen Netzfahrplan auch im Zeitraum zwischen dem Ende der\r\n\r\nAntragsfrist für den Entwurf des Netzfahrplans und dem Netzfahrplanwechsel zu beantragen.\r\n\r\n(3) Nach der Zuweisung der Zugtrassen sollte der Antragsteller vertraglich berechtigt sein, Vorschläge des Infrastruk\r\n\r\nturbetreibers für Fahrplanänderungen abzulehnen oder anzunehmen.\r\n\r\n(4) Damit die Infrastruktur und ihre Einrichtungen in gutem Zustand erhalten werden können und die Infrastruktur\r\n\r\nim Einklang mit Markterfordernissen weiterentwickelt wird, sind zeitweilige Kapazitätsbeschränkungen\r\n\r\nunumgänglich.\r\n\r\n(5) Die Antragsteller sollten frühzeitig über anstehende Kapazitätsbeschränkungen informiert werden, damit sie ihre",221,"{\"canonical_url\":null,\"normalized_sha256\":\"6f9374549aa7339e6c8e0655477ac6f91fae79fee7391e4033e1a0a5b952c710\",\"page\":1,\"source_id\":\"src_fb87aaf72d699df68d35\",\"source_sha256\":\"ee9fc6b3ca6f222446aef1bb77496672f1cf3083ed0a9ef6d493178d4e70839c\",\"source_version_id\":\"sv_ee9fc6b3ca6f222446aef1bb\"}","7a8c14465ce208d001c6c31921ec73733fe337e90d3a28da699431cc8759b2d5"],["chunk_8ee7829ecb61963a51d52e20","wiki/sources/celex-32017d2075-de-txt.md",1,"Seite 1","betrieblichen und verkehrsbezogenen Erfordernisse an die Beschränkungen der Infrastrukturkapazität anpassen\r\n\r\nkönnen. Werden Informationen zu anstehenden Kapazitätsbeschränkungen bereits zu Beginn der Antragsfrist für\r\n\r\ndie Einbeziehung von Kapazität in den jährlichen Netzfahrplan veröffentlicht, sollte es seltener notwendig werden,\r\n\r\nÄnderungen hinsichtlich bereits zugewiesener Zugtrassen vorzunehmen.\r\n\r\n(6) Bei der Wahl zwischen verschiedenen alternativen Kapazitätsbeschränkungen sollten die Infrastrukturbetreiber\r\n\r\nnicht nur ihre eigenen Kosten, sondern auch die gewerblichen und betrieblichen Sachzwänge der betroffenen\r\n\r\nAntragsteller sowie die Risiken einer Verkehrsverlagerung auf weniger umweltfreundliche Verkehrsträger\r\n\r\nberücksichtigen.\r\n\r\n(7) Die Infrastrukturbetreiber sollten transparente Kriterien für die Umleitung von Zügen und die Zuweisung\r\n\r\neingeschränkter Kapazität für verschiedene Verkehrsarten festlegen, veröffentlichen und anwenden. Dies können\r\n\r\nsie entweder gemeinsam oder einzeln jeweils nur für ihre eigenen Kapazitätsbeschränkungen vornehmen.\r\n\r\n(8) Die Infrastrukturbetreiber sollten ihre Schienennetz-Nutzungsbedingungen und Fahrplanerstellungsverfahren\r\n\r\nanpassen, um sicherzustellen, dass die mit diesem Beschluss eingeführten neuen Bestimmungen für Kapazitätsbe\r\n\r\nschränkungen rechtzeitig umgesetzt werden.\r\n\r\n(9) Hinsichtlich netzübergreifend verkehrender Züge sollten sich die Infrastrukturbetreiber abstimmen, um die Folgen\r\n\r\nvon Kapazitätsbeschränkungen für den Verkehr zu minimieren und Bauarbeiten an einer bestimmten Strecke zu\r\n\r\nsynchronisieren oder Kapazitätsbeschränkungen auf einer Umleitungsstrecke zu vermeiden.\r\n\r\n(10) Aus Gründen der Rechtssicherheit und angesichts der Zahl der erforderlichen Änderungen in Anhang VII der",191,"{\"canonical_url\":null,\"normalized_sha256\":\"6f9374549aa7339e6c8e0655477ac6f91fae79fee7391e4033e1a0a5b952c710\",\"page\":1,\"source_id\":\"src_fb87aaf72d699df68d35\",\"source_sha256\":\"ee9fc6b3ca6f222446aef1bb77496672f1cf3083ed0a9ef6d493178d4e70839c\",\"source_version_id\":\"sv_ee9fc6b3ca6f222446aef1bb\"}","f723c72aa777c1202837628b729f4dde00a62e0012b1eda4c3b927b570f29f25"],["chunk_3bd43373ab6dfb20807112d1","wiki/sources/celex-32017d2075-de-txt.md",2,"Seite 1","Richtlinie 2012/34/EU sollte der Anhang vollständig ersetzt werden. Zur Vereinfachung des Regulierungsrahmens\r\n\r\nist ein delegierter Beschluss das geeignete Rechtsinstrument, da er klare und detaillierte Bestimmungen enthält, die\r\n\r\nvon den Mitgliedstaaten nicht in nationales Recht umgesetzt werden müssen, sodass eine rasche und einheitliche\r\n\r\nDurchführung in der gesamten Union gewährleistet ist.\r\n\r\n(1) ABl. L 343 vom 14.12.2012, S. 32.",57,"{\"canonical_url\":null,\"normalized_sha256\":\"6f9374549aa7339e6c8e0655477ac6f91fae79fee7391e4033e1a0a5b952c710\",\"page\":1,\"source_id\":\"src_fb87aaf72d699df68d35\",\"source_sha256\":\"ee9fc6b3ca6f222446aef1bb77496672f1cf3083ed0a9ef6d493178d4e70839c\",\"source_version_id\":\"sv_ee9fc6b3ca6f222446aef1bb\"}","f29d6cffbf73e4c87177e6f31db61774c2e94a45e54f936de29e6394008f58d6"],["chunk_46fd7774155790f92cb5abfe","wiki/sources/celex-32017d2075-de-txt.md",3,"Seite 2","L 295/70 DE Amtsblatt der Europäischen Union 14.11.2017\r\n\r\n(11) Infolge des Zeitpunkts des Netzfahrplanwechsels gemäß Nummer 2 des Anhangs und der Vorlaufzeiten für die\r\n\r\nKoordinierung, Konsultation und Veröffentlichung der Kapazitätsbeschränkungen gemäß den Nummern 8 bis 11\r\n\r\ndes Anhangs können die Infrastrukturbetreiber die Anforderungen bezüglich der zweiten Veröffentlichungsrunde\r\n\r\ngemäß den Nummern 8 bis 11 erstmals erst für den Netzfahrplanwechsel im Dezember 2019 und bezüglich der\r\n\r\nersten Veröffentlichungsrunde im Dezember 2020 erfüllen, während die Anforderungen der Nummer 12 sowie\r\n\r\nder Nummern 14 bis 17 bereits für den Netzfahrplanwechsel im Dezember 2018 gelten.\r\n\r\n(12) Die Richtlinie 2012/34/EU sollte daher entsprechend geändert werden —\r\n\r\nHAT FOLGENDEN BESCHLUSS ERLASSEN:\r\n\r\nArtikel 1\r\n\r\nAnhang VII der Richtlinie 2012/34/EU wird durch den Anhang des vorliegenden Beschlusses ersetzt.\r\n\r\nArtikel 2\r\n\r\nDieser Beschluss tritt am zwanzigsten Tag nach seiner Veröffentlichung im Amtsblatt der Europäischen Union in Kraft.\r\n\r\nGeschehen zu Brüssel am 4. September 2017\r\n\r\nFür die Kommission\r\n\r\nDer Präsident\r\n\r\nJean-Claude JUNCKER",151,"{\"canonical_url\":null,\"normalized_sha256\":\"6f9374549aa7339e6c8e0655477ac6f91fae79fee7391e4033e1a0a5b952c710\",\"page\":2,\"source_id\":\"src_fb87aaf72d699df68d35\",\"source_sha256\":\"ee9fc6b3ca6f222446aef1bb77496672f1cf3083ed0a9ef6d493178d4e70839c\",\"source_version_id\":\"sv_ee9fc6b3ca6f222446aef1bb\"}","247674904d60640b07b29424684f4d78695aaba2bf8cd60f954cff7f2f3705a2"],["chunk_a7ae0767b0c524f059e06809","wiki/sources/celex-32017d2075-de-txt.md",4,"Seite 3","14.11.2017 DE Amtsblatt der Europäischen Union L 295/71\r\n\r\nANHANG\r\n\r\n„ANHANG VII\r\n\r\nZEITPLAN DES ZUWEISUNGSVERFAHRENS\r\n\r\n(gemäß Artikel 43)\r\n\r\n(1) Der Netzfahrplan wird einmal im Kalenderjahr erstellt.\r\n\r\n(2) Der Wechsel des Netzfahrplans erfolgt am zweiten Samstag im Dezember um 24.00 Uhr. Wird der Netzfahrplan\r\n\r\nnach den Wintermonaten angepasst, insbesondere zur Berücksichtigung etwaiger Fahrplanänderungen im\r\n\r\nregionalen Personenverkehr, so erfolgt die Umstellung am zweiten Samstag im Juni um 24.00 Uhr und bei Bedarf\r\n\r\nzu anderen Terminen. Die Infrastrukturbetreiber können sich auf abweichende Termine verständigen; in diesem Fall\r\n\r\nunterrichten sie die Kommission entsprechend, falls der internationale Verkehr betroffen sein könnte.\r\n\r\n(3) Die Antragsfrist für die Zuweisung von Fahrwegkapazität zur Aufnahme in den Netzfahrplan endet höchstens\r\n\r\nzwölf Monate vor dem Netzfahrplanwechsel. Nach Fristende eingegangene Anträge werden von den Infrastruktur\r\n\r\nbetreibern ebenfalls berücksichtigt.\r\n\r\n(4) Die Infrastrukturbetreiber tragen dafür Sorge, dass spätestens elf Monate vor dem Netzfahrplanwechsel vorläufige\r\n\r\ngrenzüberschreitende Zugtrassen in Zusammenarbeit mit den anderen betroffenen Infrastrukturbetreibern festgelegt\r\n\r\nsind. Die Infrastrukturbetreiber gewährleisten so weit wie möglich, dass diese Zugtrassen in den nachfolgenden\r\n\r\nVerfahrensschritten beibehalten werden.\r\n\r\n(5) Der Infrastrukturbetreiber erstellt und veröffentlicht spätestens vier Monate nach dem Ende der unter Nummer 3\r\n\r\ngenannten Frist einen Entwurf des Netzfahrplans.\r\n\r\n(6) Der Infrastrukturbetreiber entscheidet über Anträge, die nach dem Ende der unter Nummer 3 genannten Frist\r\n\r\neingehen, nach einem in den Schienennetz-Nutzungsbedingungen veröffentlichten Verfahren.",213,"{\"canonical_url\":null,\"normalized_sha256\":\"6f9374549aa7339e6c8e0655477ac6f91fae79fee7391e4033e1a0a5b952c710\",\"page\":3,\"source_id\":\"src_fb87aaf72d699df68d35\",\"source_sha256\":\"ee9fc6b3ca6f222446aef1bb77496672f1cf3083ed0a9ef6d493178d4e70839c\",\"source_version_id\":\"sv_ee9fc6b3ca6f222446aef1bb\"}","d2cee764b74c8a8188e0e0815ffb8cb778b2e3128ae3e7af30d833399ac58dcb"],["chunk_1f8ffede773261460b390e5e","wiki/sources/celex-32017d2075-de-txt.md",5,"Seite 3","Der Infrastrukturbetreiber kann nur dann Änderungen hinsichtlich zugewiesener Zugtrassen vornehmen, wenn dies\r\n\r\nerforderlich ist, um alle Trassenanträge bestmöglich in Einklang zu bringen, und wenn der Antragsteller, dem die\r\n\r\nTrasse zugewiesen worden war, zustimmt. Der Infrastrukturbetreiber aktualisiert den Entwurf des Netzfahrplans\r\n\r\nspätestens einen Monat vor dem Netzfahrplanwechsel, um alle nach dem Ende der unter Nummer 3 genannten\r\n\r\nFrist zugewiesenen Zugtrassen einzubeziehen.\r\n\r\n(7) Bei netzübergreifend verkehrenden Zügen, die voraussichtlich mit einer Verspätung von bis zu 10 Stunden und —\r\n\r\nab dem 14. Dezember 2019 — von bis zu 18 Stunden ankommen werden, betrachtet der Infrastrukturbetreiber\r\n\r\ndes anderen Netzes die Zugtrassen nicht als storniert und fordert nicht zur Beantragung einer anderen Zugtrasse\r\n\r\nauf, selbst wenn er sich für die Zuweisung einer anderen Zugtrasse entscheidet, es sei denn, der Antragsteller\r\n\r\ninformiert den Infrastrukturbetreiber, dass der Zug die Grenze zu dem anderen Netz nicht überqueren wird. Der\r\n\r\nInfrastrukturbetreiber teilt dem Antragsteller die aktualisierte oder neue Zugtrasse unverzüglich mit, einschließlich\r\n\r\n(falls abweichend) der Verbindung zwischen dieser Zugtrassennummer und der Zugtrassennummer der stornierten\r\n\r\nZugtrasse.\r\n\r\n(8) Hinsichtlich zeitweiliger Beschränkungen der Kapazität von Schienenstrecken, die durch Gründe wie z. B.\r\n\r\nInfrastrukturarbeiten einschließlich der damit verbundenen Geschwindigkeitsbeschränkungen, Achslast, Zuglänge,\r\n\r\nTraktion oder Lichtraumprofil bedingt sind (‚Kapazitätsbeschränkungen‘), mehr als sieben aufeinanderfolgende Tage\r\n\r\nandauern und dazu führen, dass mehr als 30 % des geschätzten Verkehrsaufkommens auf einer Schienenstrecke pro",216,"{\"canonical_url\":null,\"normalized_sha256\":\"6f9374549aa7339e6c8e0655477ac6f91fae79fee7391e4033e1a0a5b952c710\",\"page\":3,\"source_id\":\"src_fb87aaf72d699df68d35\",\"source_sha256\":\"ee9fc6b3ca6f222446aef1bb77496672f1cf3083ed0a9ef6d493178d4e70839c\",\"source_version_id\":\"sv_ee9fc6b3ca6f222446aef1bb\"}","0d5d0c83fac3951ed2a51dc78b3f8221be9bd710c44adfc939553c112296a6c4"],["chunk_ff859a4b0e9271cdebb7e99e","wiki/sources/celex-32017d2075-de-txt.md",6,"Seite 3","Tag storniert, umgeleitet oder durch andere Verkehrsträger ersetzt wird, müssen die betroffenen Infrastruktur\r\n\r\nbetreiber alle Kapazitätsbeschränkungen sowie die vorläufigen Ergebnisse einer Konsultation der Antragsteller zum\r\n\r\nersten Mal, soweit bekannt, mindestens 24 Monate und zum zweiten Mal in aktualisierter Form mindestens\r\n\r\n12 Monate vor dem betreffenden Netzfahrplanwechsel veröffentlichen.\r\n\r\n(9) Zudem führen die betroffenen Infrastrukturbetreiber ein Verfahren ein, um diese Kapazitätsbeschränkungen mit\r\n\r\ninteressierten Antragstellern, den in Artikel 40 Absatz 1 genannten Vereinigungen von Infrastrukturbetreibern und\r\n\r\nden wichtigsten Betreibern von betroffenen Serviceeinrichtungen bei der ersten Veröffentlichung zu erörtern, sofern\r\n\r\nsie sich auf mehr als ein Netz auswirken, außer wenn die Infrastrukturbetreiber und Antragsteller vereinbaren, dass\r\n\r\nein solches Verfahren nicht erforderlich ist. Die gemeinsamen Gespräche müssen zur Fahrplanerstellung beitragen,\r\n\r\nauch hinsichtlich der Bereitstellung von Umleitungsstrecken.",121,"{\"canonical_url\":null,\"normalized_sha256\":\"6f9374549aa7339e6c8e0655477ac6f91fae79fee7391e4033e1a0a5b952c710\",\"page\":3,\"source_id\":\"src_fb87aaf72d699df68d35\",\"source_sha256\":\"ee9fc6b3ca6f222446aef1bb77496672f1cf3083ed0a9ef6d493178d4e70839c\",\"source_version_id\":\"sv_ee9fc6b3ca6f222446aef1bb\"}","381be9f9d66f1aeb6688cf061c34c01782581bf8d5623d0057bc6f3f253fbac4"],["chunk_eb206caeb808f978209cc787","wiki/sources/celex-32017d2075-de-txt.md",7,"Seite 4","L 295/72 DE Amtsblatt der Europäischen Union 14.11.2017\r\n\r\n(10) Bei der ersten Veröffentlichung von Kapazitätsbeschränkungen gemäß Nummer 8 leitet der Infrastrukturbetreiber\r\n\r\neine Konsultation der Antragsteller und der wichtigsten Betreiber von betroffenen Serviceeinrichtungen zu den\r\n\r\nKapazitätsbeschränkungen ein. Ist zwischen der ersten und der zweiten Veröffentlichung der Kapazitätsbe\r\n\r\nschränkungen gemäß Nummer 11 eine Koordinierung erforderlich, konsultieren die Infrastrukturbetreiber die\r\n\r\nAntragsteller und die wichtigsten Betreiber von Serviceeinrichtungen zwischen dem Ende dieser Koordinierung und\r\n\r\nder zweiten Veröffentlichung der Kapazitätsbeschränkung ein zweites Mal.\r\n\r\n(11) Vor der Veröffentlichung der Kapazitätsbeschränkungen gemäß Nummer 8 stimmen die betroffenen Infrastruktur\r\n\r\nbetreiber, einschließlich Infrastrukturbetreibern, die von einer Zugumleitung betroffen sein könnten, Kapazitätsbe\r\n\r\nschränkungen, die zu einer Stornierung, Umleitung oder einen Ersatz durch andere Verkehrsträger führen könnten,\r\n\r\nmiteinander ab, wenn sich die Kapazitätsbeschränkungen auf mehr als ein Netz auswirken.\r\n\r\nDie Koordinierung vor der zweiten Veröffentlichung muss zu folgenden Zeitpunkten abgeschlossen sein:\r\n\r\na) spätestens 18 Monate vor dem Netzfahrplanwechsel, wenn mehr als 50 % des geschätzten Verkehrsaufkommens\r\n\r\nauf einer Schienenstrecke pro Tag für eine Dauer von mehr als 30 aufeinanderfolgenden Tagen storniert,\r\n\r\numgeleitet oder durch andere Verkehrsträger ersetzt wird;\r\n\r\nb) spätestens 13 Monate und 15 Tage vor dem Netzfahrplanwechsel, wenn mehr als 30 % des geschätzten\r\n\r\nVerkehrsaufkommens auf einer Schienenstrecke pro Tag für eine Dauer von mehr als sieben aufeinander\r\n\r\nfolgenden Tagen storniert, umgeleitet oder durch andere Verkehrsträger ersetzt wird;",218,"{\"canonical_url\":null,\"normalized_sha256\":\"6f9374549aa7339e6c8e0655477ac6f91fae79fee7391e4033e1a0a5b952c710\",\"page\":4,\"source_id\":\"src_fb87aaf72d699df68d35\",\"source_sha256\":\"ee9fc6b3ca6f222446aef1bb77496672f1cf3083ed0a9ef6d493178d4e70839c\",\"source_version_id\":\"sv_ee9fc6b3ca6f222446aef1bb\"}","3f0fd603a7e6be8c73fcc48d41b9c66a5f23fc785131dbc329d0cc407d83276c"],["chunk_3553237a533869c98ce0a180","wiki/sources/celex-32017d2075-de-txt.md",8,"Seite 4","c) spätestens 13 Monate und 15 Tage vor dem Netzfahrplanwechsel, wenn mehr als 50 % des geschätzten\r\n\r\nVerkehrsaufkommens auf einer Schienenstrecke pro Tag für eine Dauer von bis zu sieben aufeinanderfolgenden\r\n\r\nTagen storniert, umgeleitet oder durch andere Verkehrsträger ersetzt wird.\r\n\r\nSoweit erforderlich, laden die Infrastrukturbetreiber die auf den betroffenen Strecken tätigen Antragsteller und die\r\n\r\nwichtigsten Betreiber der betroffenen Serviceeinrichtungen zur Teilnahme an dieser Koordinierung ein.\r\n\r\n(12) Hinsichtlich Kapazitätsbeschränkungen mit einer Dauer von bis zu sieben aufeinanderfolgenden Tagen, die nicht\r\n\r\ngemäß Nummer 8 veröffentlicht werden müssen, aber dazu führen, dass mehr als 10 % des geschätzten Verkehrs\r\n\r\naufkommens auf einer Schienenstrecke pro Tag storniert, umgeleitet oder durch andere Verkehrsträger ersetzt wird,\r\n\r\nund die in der folgenden Fahrplanperiode auftreten und dem Infrastrukturbetreiber spätestens 6 Monate und\r\n\r\n15 Tage vor dem Netzfahrplanwechsel bekannt werden, konsultiert der Infrastrukturbetreiber die betroffenen\r\n\r\nAntragsteller zu den vorgesehenen Kapazitätsbeschränkungen und teilt die aktualisierten Kapazitätsbeschränkungen\r\n\r\nmindestens vier Monate vor dem Netzfahrplanwechsel mit. Der Infrastrukturbetreiber stellt die Einzelheiten zu den\r\n\r\nangebotenen Zugtrassen für Personenzüge spätestens vier Monate und für Güterzüge spätestens einen Monat vor\r\n\r\ndem Beginn der Kapazitätsbeschränkung bereit, außer wenn der Infrastrukturbetreiber und die betroffenen\r\n\r\nAntragsteller eine kürzere Vorlaufzeit vereinbaren.\r\n\r\n(13) Die Infrastrukturbetreiber können auf der Grundlage einer Konsultation mit Antragstellern und den Betreibern von\r\n\r\nServiceeinrichtungen entscheiden, strengere Schwellen für Kapazitätsbeschränkungen anzuwenden, die auf",215,"{\"canonical_url\":null,\"normalized_sha256\":\"6f9374549aa7339e6c8e0655477ac6f91fae79fee7391e4033e1a0a5b952c710\",\"page\":4,\"source_id\":\"src_fb87aaf72d699df68d35\",\"source_sha256\":\"ee9fc6b3ca6f222446aef1bb77496672f1cf3083ed0a9ef6d493178d4e70839c\",\"source_version_id\":\"sv_ee9fc6b3ca6f222446aef1bb\"}","760e9324420fb29768331771355e76a35e98a504e6e68fffc2b2f353127af997"],["chunk_1ffe4f2f60bc8f3e2c677829","wiki/sources/celex-32017d2075-de-txt.md",9,"Seite 4","niedrigeren Prozentsätzen des geschätzten Verkehrsaufkommens oder einer kürzeren Dauer beruhen, als nach\r\n\r\ndiesem Anhang erforderlich wäre, oder neben den Kriterien aus diesem Anhang weitere Kriterien anzuwenden. Sie\r\n\r\nveröffentlichen die Schwellen und Kriterien für die Zusammenfassung von Kapazitätsbeschränkungen in ihren\r\n\r\nSchienennetz-Nutzungsbedingungen nach Anhang IV Nummer 3.\r\n\r\n(14) Der Infrastrukturbetreiber kann entscheiden, die unter den Nummer 8 bis 12 genannten Fristen nicht anzuwenden,\r\n\r\nwenn die Kapazitätsbeschränkung für die Wiederherstellung eines sicheren Zugbetriebs erforderlich ist, der\r\n\r\nZeitpunkt der Beschränkungen nicht der Kontrolle des Infrastrukturbetreibers unterliegt, die Anwendung dieser\r\n\r\nFristen nicht kostenwirksam oder mit nicht zu vertretenden Nachteilen für Lebensdauer oder Zustand von Anlagen\r\n\r\nverbunden wäre oder wenn alle betroffenen Antragsteller zustimmen. In diesen Fällen sowie im Falle anderer\r\n\r\nKapazitätsbeschränkungen, die nicht gemäß anderen Bestimmungen dieses Anhangs einer Konsultation unterzogen\r\n\r\nwerden müssen, konsultiert der Infrastrukturbetreiber die betroffenen Antragsteller und die wichtigsten Betreiber\r\n\r\nvon Serviceeinrichtungen umgehend.\r\n\r\n(15) Die vom Infrastrukturbetreiber bei Maßnahmen gemäß den Nummern 8, 12 oder 14 bereitzustellenden\r\n\r\nInformationen müssen Folgendes umfassen:\r\n\r\na) den vorgesehenen Tag,\r\n\r\nb) die Tageszeit und, sobald möglich, Uhrzeit des Beginns und Endes der Kapazitätsbeschränkung,\r\n\r\nc) den von der Kapazitätsbeschränkung betroffenen Streckenabschnitt und\r\n\r\nd) gegebenenfalls die Kapazität der Umleitungsstrecken.\r\n\r\nDer Infrastrukturbetreiber veröffentlicht diese Informationen oder einen entsprechenden Link zur Fundstelle gemäß",202,"{\"canonical_url\":null,\"normalized_sha256\":\"6f9374549aa7339e6c8e0655477ac6f91fae79fee7391e4033e1a0a5b952c710\",\"page\":4,\"source_id\":\"src_fb87aaf72d699df68d35\",\"source_sha256\":\"ee9fc6b3ca6f222446aef1bb77496672f1cf3083ed0a9ef6d493178d4e70839c\",\"source_version_id\":\"sv_ee9fc6b3ca6f222446aef1bb\"}","20b9b1cd2fcf196ffa7a9a07c0c53759bce75a9f11faeee1f990816417239a32"],["chunk_c1c8e0762dc94e8f96134e35","wiki/sources/celex-32017d2075-de-txt.md",10,"Seite 4","Anhang IV Nummer 3 in seinen Schienennetz-Nutzungsbedingungen. Der Infrastrukturbetreiber muss diese\r\n\r\nInformationen laufend aktualisieren.",14,"{\"canonical_url\":null,\"normalized_sha256\":\"6f9374549aa7339e6c8e0655477ac6f91fae79fee7391e4033e1a0a5b952c710\",\"page\":4,\"source_id\":\"src_fb87aaf72d699df68d35\",\"source_sha256\":\"ee9fc6b3ca6f222446aef1bb77496672f1cf3083ed0a9ef6d493178d4e70839c\",\"source_version_id\":\"sv_ee9fc6b3ca6f222446aef1bb\"}","8f58242004b45682875dbd3f9e53a9280bc0831a1649bcb848e3cec8bc659d77"],["chunk_ae0509aa0537a0010b129ff2","wiki/sources/celex-32017d2075-de-txt.md",11,"Seite 5","14.11.2017 DE Amtsblatt der Europäischen Union L 295/73\r\n\r\n(16) Hinsichtlich Kapazitätsbeschränkungen, die mindestens 30 aufeinanderfolgende Tage lang andauern und mehr als\r\n\r\n50 % des geschätzten Verkehrsaufkommens auf einer Schienenstrecke betreffen, muss der Infrastrukturbetreiber den\r\n\r\nAntragstellern auf deren Anfrage hin während der ersten Konsultationsrunde einen Vergleich der Bedingungen bei\r\n\r\nmindestens zwei alternativen Kapazitätsbeschränkungen bereitstellen. Der Infrastrukturbetreiber gestaltet diese\r\n\r\nAlternativen gemeinsam mit den Antragstellern anhand der Angaben, die ihm die Antragsteller zum Zeitpunkt\r\n\r\nihrer Anfrage bereitstellen.\r\n\r\nDer Vergleich muss für jede Alternative mindestens Folgendes umfassen:\r\n\r\na) die Dauer der Kapazitätsbeschränkung,\r\n\r\nb) die zu erwartenden ungefähr zu zahlenden Infrastrukturentgelte,\r\n\r\nc) die verfügbare Kapazität auf Umleitungsstrecken,\r\n\r\nd) die verfügbaren alternativen Strecken und\r\n\r\ne) die ungefähren Fahrtzeiten.\r\n\r\nBevor er zwischen den alternativen Kapazitätsbeschränkungen wählt, konsultiert der Infrastrukturbetreiber die\r\n\r\ninteressierten Antragsteller und berücksichtigt die Auswirkungen der verschiedenen Alternativen auf diese\r\n\r\nAntragsteller und die Nutzer der Dienste.\r\n\r\n(17) Im Falle von Kapazitätsbeschränkungen, die mehr als 30 aufeinanderfolgende Tage andauern und mehr als 50 %\r\n\r\ndes geschätzten Verkehrsaufkommens auf einer Schienenstrecke betreffen, muss der Infrastrukturbetreiber Kriterien\r\n\r\nfestlegen, welche Züge jeder Verkehrsart umgeleitet werden sollten, und dabei die gewerblichen und betrieblichen\r\n\r\nSachzwänge des Antragstellers berücksichtigen, soweit diese betrieblichen Sachzwänge nicht aus unternehmerischen\r\n\r\noder organisatorischen Entscheidungen des Antragstellers resultieren, unbeschadet des Ziels gemäß Artikel 30",205,"{\"canonical_url\":null,\"normalized_sha256\":\"6f9374549aa7339e6c8e0655477ac6f91fae79fee7391e4033e1a0a5b952c710\",\"page\":5,\"source_id\":\"src_fb87aaf72d699df68d35\",\"source_sha256\":\"ee9fc6b3ca6f222446aef1bb77496672f1cf3083ed0a9ef6d493178d4e70839c\",\"source_version_id\":\"sv_ee9fc6b3ca6f222446aef1bb\"}","6040efd041cafbb9bb054277fb87d508ca3a4dae26f61c79ca6c1937402a1f84"],["chunk_c9746e39ec9ec628a11f73d2","wiki/sources/celex-32017d2075-de-txt.md",12,"Seite 5","Absatz 1, die Kosten des Infrastrukturbetreibers zu senken. Der Infrastrukturbetreiber veröffentlicht diese Kriterien\r\n\r\nzusammen mit einer vorläufigen Zuweisung der verbleibenden Kapazität für die einzelnen Arten von Schienenver\r\n\r\nkehrsdiensten im Rahmen der Maßnahmen gemäß Nummer 8 in seinen Schienennetz-Nutzungsbedingungen. Nach\r\n\r\ndem Ende der Konsultation und unbeschadet der Verpflichtungen des Infrastrukturbetreibers gemäß Anhang IV\r\n\r\nNummer 3 stellt der Infrastrukturbetreiber den betroffenen Eisenbahnunternehmen auf der Grundlage der\r\n\r\nRückmeldungen der Antragsteller eine vorläufige Aufschlüsselung nach Art der Dienstleistung für die verbleibende\r\n\r\nKapazität bereit.“",79,"{\"canonical_url\":null,\"normalized_sha256\":\"6f9374549aa7339e6c8e0655477ac6f91fae79fee7391e4033e1a0a5b952c710\",\"page\":5,\"source_id\":\"src_fb87aaf72d699df68d35\",\"source_sha256\":\"ee9fc6b3ca6f222446aef1bb77496672f1cf3083ed0a9ef6d493178d4e70839c\",\"source_version_id\":\"sv_ee9fc6b3ca6f222446aef1bb\"}","f4bc42731942b3bd50687b3ea5f540b1f41219f75051a026c9b15a4e76a29b64"],["chunk_dbba9e8d8ff88994e53eab19","wiki/sources/changelog-baufplo-api-evu-2-17-0-data.md",0,"Seite 1","DB\r\n\r\nChangelog BauFplo API EVU\r\n\r\nInhaltsverzeichnis\r\n\r\n1. Einleitung. . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . 1\r\n\r\n2. Version 2.17.0 . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . 1\r\n\r\n2.1. Zusammenfassung der Auswirkungen . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . 1\r\n\r\n3. Version 2.16.4 . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . 1\r\n\r\n3.1. Zusammenfassung der Auswirkungen . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . 1\r\n\r\n3.2. Detaillierte Änderungen. . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . 1\r\n\r\n4. Version 2.16.1 . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . 2\r\n\r\n4.1. Zusammenfassung der Auswirkungen . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . 2\r\n\r\n4.2. Detaillierte Änderungen. . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . 2\r\n\r\n5. Version 2.8.0 . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . 3\r\n\r\n5.1. Zusammenfassung der Auswirkungen . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . 3\r\n\r\n5.2. Detaillierte Änderungen. . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . 3\r\n\r\n6. Version 2.2.0 . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . 4\r\n\r\n1. Einleitung\r\n\r\nDiese Änderungsübersicht der Schnittstellenbeschreibung der Digitalen",700,"{\"canonical_url\":null,\"normalized_sha256\":\"910e8db9cbe296cd124592f82fabbfe4ac780700209d436e5c31aa4de59cc428\",\"page\":1,\"source_id\":\"src_9a8ac84849939f0108ef\",\"source_sha256\":\"c78844566eba2b02b0ca49e411141537e83f45f357a5682c0ae52f5858b99ccb\",\"source_version_id\":\"sv_9aacda759a56475d3f64f6e0\"}","8871c6fdced54e5f70468706ea36a29656ea3bf9b816924ba2692cff47c8e34d"],["chunk_32fb7d0aa6862651a4ec8e78","wiki/sources/changelog-baufplo-api-evu-2-17-0-data.md",1,"Seite 1","Baufahrplananordnung wird fortlaufend gepflegt und informiert über Anpassungen,\r\n\r\nErweiterungen und Korrekturen der Schnittstelle. Ziel ist es, relevante Änderungen kompakt\r\n\r\ndarzustellen und die Bewertung möglicher Auswirkungen auf Ihre Systeme zu unterstützen.\r\n\r\nBitte prüfen Sie die aufgeführten Punkte und planen Sie erforderliche Anpassungen\r\n\r\nrechtzeitig ein. Bei Fragen nutzen Sie bitte die bekannten Support-Kanäle.\r\n\r\n2. Version 2.17.0\r\n\r\n2.1. Zusammenfassung der Auswirkungen\r\n\r\nErhöhung der Versionsnummer, um der bereitgestellten Version auf dem DB API\r\n\r\nMarketplace zu entsprechen. Keine weiteren Änderungen im Vergleich zu Version 2.16.4.\r\n\r\n3. Version 2.16.4\r\n\r\n3.1. Zusammenfassung der Auswirkungen\r\n\r\n▮ Breaking Changes: keine\r\n\r\n▮ Deprecations ohne Ersatz:\r\n\r\n▮ „Baumassnahme\"\r\n\r\n▮ „nummer\"\r\n\r\n▮ „zeitraum\"\r\n\r\n▮ „artDerArbeiten\"\r\n\r\n3.2. Detaillierte Änderungen\r\n\r\nTabelle 1. Beschreibung der Änderungen zwischen Version 2.16.4 und 2.16.1\r\n\r\nChangelog BauFplo API EVU 1",121,"{\"canonical_url\":null,\"normalized_sha256\":\"910e8db9cbe296cd124592f82fabbfe4ac780700209d436e5c31aa4de59cc428\",\"page\":1,\"source_id\":\"src_9a8ac84849939f0108ef\",\"source_sha256\":\"c78844566eba2b02b0ca49e411141537e83f45f357a5682c0ae52f5858b99ccb\",\"source_version_id\":\"sv_9aacda759a56475d3f64f6e0\"}","fdb2a5238bcc80d9c42a6e454ff25f35ff9749ddfc6748472d709b10b2241d2f"],["chunk_ee533dfa6e4ee31d78e0b364","wiki/sources/changelog-baufplo-api-evu-2-17-0-data.md",2,"Seite 2","DB\r\n\r\nThema Änderung\r\n\r\nBaumassnahme Das Element „Baumassnahme\" ist deprecated\r\n\r\nmit dem Hinweis in der Beschreibung, dass es\r\n\r\nnur noch für das Fahrplanjahr 2026 relevant ist\r\n\r\nund ab Fahrplanjahr 2027 nicht mehr befüllt wird.\r\n\r\nBaumassnahme > properties > nummer Attribut „nummer\" ist deprecated mit dem\r\n\r\nHinweis in der Beschreibung, dass es nur noch\r\n\r\nfür das Fahrplanjahr 2026 relevant ist und ab\r\n\r\nFahrplanjahr 2027 nicht mehr befüllt wird.\r\n\r\nBaumassnahme > properties > zeitraum Attribut „zeitraum\" ist deprecated mit dem\r\n\r\nHinweis in der Beschreibung, dass es nur noch\r\n\r\nfür das Fahrplanjahr 2026 relevant ist und ab\r\n\r\nFahrplanjahr 2027 nicht mehr befüllt wird.\r\n\r\nBaumassnahme > properties > artDerArbeiten Attribut „artDerArbeiten\" ist deprecated mit dem\r\n\r\nHinweis in der Beschreibung, dass es nur noch\r\n\r\nfür das Fahrplanjahr 2026 relevant ist und ab\r\n\r\nFahrplanjahr 2027 nicht mehr befüllt wird.\r\n\r\n4. Version 2.16.1\r\n\r\n4.1. Zusammenfassung der Auswirkungen\r\n\r\n▮ Breaking Changes: keine\r\n\r\n▮ Deprecations mit Ersatz:\r\n\r\n▮ „hatNotbremsueberbrueckung\" am Zugverband wird ersetzt durch\r\n\r\n„notbremsueberbrueckung\" an den Regelungen\r\n\r\n▮ „hatNotbremsueberbrueckung\" am RahmendatenZugverband wird ersetzt durch\r\n\r\n„notbremsueberbrueckung\" an den Regelungen\r\n\r\n▮ Additive Erweiterungen:\r\n\r\n▮ „keineangabe\" am Fahrplan\r\n\r\n▮ „startBetriebsstelleRoute\"\r\n\r\n▮ „zielBetriebsstelleRoute\"\r\n\r\n▮ „bpolMeldepflichtig\"\r\n\r\n▮ „leichterNahverkehrstriebwagen\"\r\n\r\n▮ „notbremsueberbrueckung\"\r\n\r\n4.2. Detaillierte Änderungen\r\n\r\nTabelle 2. Beschreibung der Änderungen zwischen Version 2.16.1 und 2.8.0\r\n\r\nThema Änderung\r\n\r\nFahrplan > properties > keineangabe Neues Element „keineangabe\" vom Typ\r\n\r\n„KeineAngabe\". Enthält Informationen zu Teilen\r\n\r\ndes Laufwegs, bei denen keine\r\n\r\nFahrplanangaben erfolgen (mit Angaben zu\r\n\r\nStart-/Zielbetriebsstelle, Einreihung, Art und",230,"{\"canonical_url\":null,\"normalized_sha256\":\"910e8db9cbe296cd124592f82fabbfe4ac780700209d436e5c31aa4de59cc428\",\"page\":2,\"source_id\":\"src_9a8ac84849939f0108ef\",\"source_sha256\":\"c78844566eba2b02b0ca49e411141537e83f45f357a5682c0ae52f5858b99ccb\",\"source_version_id\":\"sv_9aacda759a56475d3f64f6e0\"}","f7c378a84c3905cecdc374f3ad3e247a6f293d33c9c1260109bba94e96be0cba"],["chunk_99d0ef6198a77ada56e95a0c","wiki/sources/changelog-baufplo-api-evu-2-17-0-data.md",3,"Seite 2","Beschreibung).\r\n\r\nChangelog BauFplo API EVU 2",6,"{\"canonical_url\":null,\"normalized_sha256\":\"910e8db9cbe296cd124592f82fabbfe4ac780700209d436e5c31aa4de59cc428\",\"page\":2,\"source_id\":\"src_9a8ac84849939f0108ef\",\"source_sha256\":\"c78844566eba2b02b0ca49e411141537e83f45f357a5682c0ae52f5858b99ccb\",\"source_version_id\":\"sv_9aacda759a56475d3f64f6e0\"}","bc47b6132e4ed1ce599ba17c8df600695a9b02baab9d88db8c48012e68716f57"],["chunk_e4fcbeb029e49b726bac725f","wiki/sources/changelog-baufplo-api-evu-2-17-0-data.md",4,"Seite 3","DB\r\n\r\nThema Änderung\r\n\r\nRahmendaten > properties > Attribut „startBetriebsstelleRoute\" neu. Erste\r\n\r\nstartBetriebsstelleRoute Betriebsstelle der Gesamtzugroute (weicht von\r\n\r\n„startBetriebsstelle\" ab, wenn der Zug im\r\n\r\nFremdnetz beginnt).\r\n\r\nRahmendaten > properties > Attribut „zielBetriebsstelleRoute\" neu. Letzte\r\n\r\nzielBetriebsstelleRoute Betriebsstelle der Gesamtzugroute (weicht von\r\n\r\n„zielBetriebsstelle\" ab, wenn der Zug im\r\n\r\nFremdnetz endet).\r\n\r\nRahmendaten > properties > bpolMeldepflichtig Attribut „bpolMeldepflichtig\" neu. Gibt an, ob die\r\n\r\nZugtrasse an die Bundespolizei gemeldet\r\n\r\nwerden muss.\r\n\r\nRahmendatenZugcharakteristik > properties > Attribut „leichterNahverkehrstriebwagen\" neu.\r\n\r\nleichterNahverkehrstriebwagen Angabe, ob es sich um einen leichten\r\n\r\nNahverkehrstriebwagen handelt.\r\n\r\nRahmendatenRegelungen > properties > Attribut „notbremsueberbrueckung\" neu. Angabe,\r\n\r\nnotbremsueberbrueckung ob eine NBÜ erforderlich ist.\r\n\r\nRahmendatenZugverband > properties > Attribut „hatNotbremsueberbrueckung\" ist\r\n\r\nhatNotbremsueberbrueckung deprecated mit dem Hinweis in der\r\n\r\nBeschreibung, dass „notbremsueberbrueckung\"\r\n\r\ngilt. Bitte nutzen Sie dieses Attribut nicht mehr.\r\n\r\nZugverband > properties > Attribut „hatNotbremsueberbrueckung\" ist\r\n\r\nhatNotbremsueberbrueckung deprecated mit dem Hinweis in der\r\n\r\nBeschreibung, dass „notbremsueberbrueckung\"\r\n\r\ngilt. Bitte nutzen Sie dieses Attribut nicht mehr.\r\n\r\n5. Version 2.8.0\r\n\r\n5.1. Zusammenfassung der Auswirkungen\r\n\r\n▮ Breaking Changes:\r\n\r\n▮ „zugfolgevermerk“ entfernt (Ablösung über „hinweise“)\r\n\r\n▮ Deprecations mit Ersatz:\r\n\r\n▮ „abfahrzeit“ wird ersetzt durch „abfahrtuhrzeit“\r\n\r\n▮ „ankunftzeit“ wird ersetzt durch „ankunftuhrzeit“\r\n\r\n▮ „betriebsname“ am Buchfahrplanverweis wird ersetzt durch „betriebsname“ am\r\n\r\nLaufwegpunkt\r\n\r\n▮ Additive Erweiterungen:\r\n\r\n▮ „strecke“",194,"{\"canonical_url\":null,\"normalized_sha256\":\"910e8db9cbe296cd124592f82fabbfe4ac780700209d436e5c31aa4de59cc428\",\"page\":3,\"source_id\":\"src_9a8ac84849939f0108ef\",\"source_sha256\":\"c78844566eba2b02b0ca49e411141537e83f45f357a5682c0ae52f5858b99ccb\",\"source_version_id\":\"sv_9aacda759a56475d3f64f6e0\"}","31d593a16f79d724eff6939e9469416e1992a6e83f33faa0fda3620e1ce18492"],["chunk_ad4d19944316e64c15c902a0","wiki/sources/changelog-baufplo-api-evu-2-17-0-data.md",5,"Seite 3","▮ Validierungsänderung:\r\n\r\n▮ „minItems“ bei „textbausteine“ entfällt\r\n\r\n5.2. Detaillierte Änderungen\r\n\r\nTabelle 3. Beschreibung der Änderungen zwischen Version 2.8.0 und 2.2.0\r\n\r\nChangelog BauFplo API EVU 3",25,"{\"canonical_url\":null,\"normalized_sha256\":\"910e8db9cbe296cd124592f82fabbfe4ac780700209d436e5c31aa4de59cc428\",\"page\":3,\"source_id\":\"src_9a8ac84849939f0108ef\",\"source_sha256\":\"c78844566eba2b02b0ca49e411141537e83f45f357a5682c0ae52f5858b99ccb\",\"source_version_id\":\"sv_9aacda759a56475d3f64f6e0\"}","4924d4bc450e5cd7841732fe4d34c77cf4c050238d4c30211cc65769657c3a81"],["chunk_a3e6fb4999ffa6450caa01e6","wiki/sources/changelog-baufplo-api-evu-2-17-0-data.md",6,"Seite 4","DB\r\n\r\nThema Änderung\r\n\r\nAllgemeines > properties > textbausteine Attribut „minItems“ entfällt.\r\n\r\nLaufwegpunkt > properties > betriebsname Attribut „betriebsname“ am „Laufwegpunkt“ neu.\r\n\r\nBuchfahrplanverweis > properties > Attribut „betriebsname“ am\r\n\r\nbetriebsname „Buchfahrplanverweis“ ist deprecated, da dieser\r\n\r\nam „Laufwegpunkt“ gepflegt wird.\r\n\r\nLaufwegpunkt > properties > abfahrtuhrzeit Attribut „abfahrtuhrzeit“ neu.\r\n\r\nLaufwegpunkt > properties > abfahrzeit Attribut „abfahrzeit“ ist deprecated mit dem\r\n\r\nHinweis in der Beschreibung, dass\r\n\r\n„abfahrtuhrzeit“ gilt. Bitte nutzen Sie dieses\r\n\r\nAttribut nicht mehr.\r\n\r\nLaufwegpunkt > properties > ankunftuhrzeit Attribut „ankunftuhrzeit“ neu.\r\n\r\nLaufwegpunkt > properties > ankunftzeit Attribut „ankunftzeit“ ist deprecated mit dem\r\n\r\nHinweis in der Beschreibung, dass\r\n\r\n„ankunftuhrzeit“ gilt. Bitte nutzen Sie dieses\r\n\r\nAttribut nicht mehr.\r\n\r\nLaufwegpunkt > properties > strecke Attribut „strecke“ wurde hinzugefügt.\r\n\r\nLaufwegpunkt > properties > zugfolgevermerk Attribut „zugfolgevermerk“ entfällt. Ein\r\n\r\nZugfolgevermerk wird über die „hinweise“ am\r\n\r\n„Laufwegpunkt“ übergeben.\r\n\r\n6. Version 2.2.0\r\n\r\nInitialerstellung\r\n\r\nChangelog BauFplo API EVU 4",139,"{\"canonical_url\":null,\"normalized_sha256\":\"910e8db9cbe296cd124592f82fabbfe4ac780700209d436e5c31aa4de59cc428\",\"page\":4,\"source_id\":\"src_9a8ac84849939f0108ef\",\"source_sha256\":\"c78844566eba2b02b0ca49e411141537e83f45f357a5682c0ae52f5858b99ccb\",\"source_version_id\":\"sv_9aacda759a56475d3f64f6e0\"}","d524a3f05a9243d40f4d493b0a469218585037c2dc81129cbfa7170021e5081c"]]');
