INSERT INTO wiki_chunks (id,page_path,ordinal,heading_path,text,token_count,source_refs_json,content_sha) SELECT json_extract(value,'$[0]'),json_extract(value,'$[1]'),json_extract(value,'$[2]'),json_extract(value,'$[3]'),json_extract(value,'$[4]'),json_extract(value,'$[5]'),json_extract(value,'$[6]'),json_extract(value,'$[7]') FROM json_each('[["chunk_3a6ea91b0ec1608525ea441b","wiki/sources/click-ride.md",0,"Inhalt","*Entdecken Sie jetzt unsere Web-App* [*Click&Ride*](https://clickandride.dbinfrago.com/ \"Wird in einem neuen Tab geöffnet\") *und starten Sie mit uns in eine neue Zeitrechnung des Schienengüterverkehrs. Kurzfristige Buchungen können Sie ab sofort ganz einfach und schnell – in nur 3 Minuten – vornehmen. Und das ab 7 Tagen und bis 45 Minuten vor der gewünschten Fahrt. Ob Überführungsfahrten, Leerfahrten, Triebfahrzeugfahrten oder Fahrten mit Standardgüterzügen mit kurzem Planungsvorlauf: Ihren Fahrplan erhalten Sie dank unseres volldigitalen Systems in Echtzeit direkt auf Ihren PC, Tablet oder Smartphone.*\r\n\r\n**Entlastung für Ihren Arbeitsalltag.**\r\n\r\n![](https://www.dbinfrago.com/resource/image/10907254/4:3/576/432/3fe5dc35c83976447bfd7ad71b4bdce0/7A25B8050B22E93FC8654BA0300C7EA3/clickandride_Mann-mit-Tablet.png)\r\n\r\nSpontane Anfragen Ihrer Kund:innen? Eine dringende Überführung einer Lok zum Einsatz? Kurzfristige Änderungswünsche Ihrer Kund:innen?\r\n\r\nAll das kostet Sie mit Click&Ride nur noch ein paar Klicks. So können Sie Zeit wieder aufholen und kurzfristigen Aufträgen entspannt entgegensehen.\r\n\r\n**Click&Ride auf einen Blick.**\r\n\r\n**So funktioniert es:**\r\n\r\n**1\\. Einfach Web-App öffnen.** Bequem auf dem Desktop-PC, Tablet oder unterwegs auf dem Smartphone.\r\n\r\n**2\\. Start, Ziel, Wunschzeit und Parameter eingeben.** Einfach die Art Ihrer Lok, Gewicht, Länge, etc. definieren. Ihre Trassenanmeldung kann wahlweise zu gewünschter Abfahrts- oder Ankunftszeit erfolgen.\r\n\r\n**3\\. In spätestens 3 Minuten Ihr Angebot erhalten.** Ihre Trasse ist ab dem Moment für 10 Minuten reserviert. So können Sie in Ruhe entscheiden und entspannt buchen.\r\n\r\n[Jetzt Click&Ride starten](https://clickandride.dbinfrago.com/ \"Wird in einem neuen Tab geöffnet\")\r\n\r\n**Alle Vorteile auf einen Blick.**",211,"{\"canonical_url\":\"https://www.dbinfrago.com/web/schienennetz/leistungen/trassen/trassenbestellung/trassenanmeldung/click_and_ride-10907236\",\"normalized_sha256\":\"8d41ec8cb8e71bddb957af0f0b485d4120af7639a8996a6ff0c2021d1619e916\",\"page\":null,\"source_id\":\"src_87a0d1da7ffe15350d9d\",\"source_sha256\":\"a564b36a60a9e35982e72efd9cc2532b4b6399e780ae1be060c0104a5bf66e09\",\"source_version_id\":\"sv_2e22d860175ac7f66366cbe9\"}","2a0be3ded2f71b2380c4a13ea0b203b4b3e7c6ba78c522a20fa95da5387daf86"],["chunk_22ef313ae3a0cd892f35ff60","wiki/sources/click-ride.md",1,"Inhalt","- kurzfristig regionale oder überregionale Trassen buchen\r\n- ab 7 Tage bis 45 Minuten vor Wunschabfahrtszeit\r\n- direkter Zugriff auf Click&Ride\r\n- Ihre Trassenanmeldung und die Zugfahrt sind fast zeitgleich möglich\r\n- nationaler Güterverkehr\r\n\r\n**Hinweise zu Updates - Wartung ohne langes Warten.**\r\n\r\nWir verbessern unsere Web-App Click&Ride ständig für Sie weiter. Dazu gehören regelmäßige Updates und Wartungen, die Sie gut in Ihren Arbeitsablauf einplanen können. Jeden Mittwoch machen wir immer zur gleichen Zeit von 6 Uhr bis 8 Uhr und jeden Sonntag von 2 Uhr bis 3 Uhr eine Wartungspause. Direkt danach steht Ihnen unsere Web-App natürlich wieder uneingeschränkt zur Verfügung.\r\n\r\nHinweis: Sollte Ihnen nach der Wartungspause immer noch die Wartungsseite in unserer Web-App angezeigt werden, laden Sie die Seite bitte mit „Strg und F5“ einfach neu.\r\n\r\n**Unsere FAQs.**\r\n\r\nHier finden Sie Antworten auf häufig gestellte fachliche und technische Fragen. Klicken Sie einfach eine passende Frage an und die entsprechende Antwort erscheint. Wenn Sie darüber hinaus weitere Unterstützung benötigen, nutzen Sie einfach das Kontaktformular auf dieser Website.\r\n\r\n**FAQs zur Bedienung**\r\n\r\n**1\\. Welchen Browser soll ich nutzen?**\r\n\r\nBitte verwenden Sie ausschließlich Google Chrome. Unsere Web-App Click&Ride ist für diesen Browser optimiert.\r\n\r\n**2\\. Wie erhalte ich meine Zugangsdaten?**\r\n\r\nUm unsere Web-App zu nutzen, benötigen Sie Ihre Zugangsdaten. Es gibt zwei Wege diese anzufordern.\r\n\r\n1\\. Nehmen Sie Kontakt zu den Administratoren in Ihrem Unternehmen auf. Sie können Sie freischalten und Ihnen die Zugangsdaten zur Verfügung stellen.",233,"{\"canonical_url\":\"https://www.dbinfrago.com/web/schienennetz/leistungen/trassen/trassenbestellung/trassenanmeldung/click_and_ride-10907236\",\"normalized_sha256\":\"8d41ec8cb8e71bddb957af0f0b485d4120af7639a8996a6ff0c2021d1619e916\",\"page\":null,\"source_id\":\"src_87a0d1da7ffe15350d9d\",\"source_sha256\":\"a564b36a60a9e35982e72efd9cc2532b4b6399e780ae1be060c0104a5bf66e09\",\"source_version_id\":\"sv_2e22d860175ac7f66366cbe9\"}","7863307ab4d86f506787f1efcbcfc137f4f4bc787b4845eeb60eeee2e4e50bab"],["chunk_6253c95b22b6d392404807e7","wiki/sources/click-ride.md",2,"Inhalt","2\\. Wenn Sie die Administratoren in Ihrem Unternehmen nicht kennen, unterstützt Sie Ihr:e Kundenberater:in aus Ihrer Region gerne und legt Sie im System an. Nutzen Sie einfach nebenstehenden Link zu unserer Kontaktseite.\r\n\r\nMöchten Sie selbst Administrator:in für Ihr Unternehmen werden?Alle Antworten zu dieser Frage finden Sie in unseren FAQs unter Punkt 4.\r\n\r\n**3\\. Wie melde ich mich an?**\r\n\r\n- Nachdem Ihre Daten von den Administratoren oder von unseren Kundenberater:innen angelegt worden sind, erhalten Sie via E-Mail eine Einladung zur Registrierung und Anmeldung.\r\n\r\n![](https://www.dbinfrago.com/resource/image/10907240/4:3/576/432/15f2a5210119b69cc4bc4bd70f9f843/7CA2C34B127A47E196B18BD11288694A/clickandride_Anmeldung-Bild-1.jpg)\r\n\r\n- Klicken Sie auf den Link „Registrierung für das Kundenportal (Beta)“ und öffnen Sie in Google Chrome die Seite, um den Registrierungsprozess zu starten.\r\n\r\n![](https://www.dbinfrago.com/resource/image/10907244/4:3/576/432/e83ebe1becd89858b03effc532f47653/6B625C46BE90FAF26A34EF693FB83F48/clickandride_Anmeldung-Bild-2.jpg)\r\n\r\n- Bitte füllen Sie alle erforderlichen Felder (mit \\* markiert) aus und definieren Sie Ihr Passwort. Mit einem Häkchen akzeptieren Sie die Datenschutz- und Nutzungsbedingungen. Jetzt brauchen Sie nur noch auf den Button „Registrieren“ zu klicken.\r\n\r\n![](https://www.dbinfrago.com/resource/image/10907246/4:3/576/432/4a273e62331024a733de9009345dc3b8/5378EA6EE88C4907415DFF31269B0348/clickandride_Anmeldung-Bild-3.jpg)\r\n\r\n- Per E-Mail erhalten Sie jetzt umgehend Ihren Benutzernamen zugesandt.\r\n\r\n![](https://www.dbinfrago.com/resource/image/10907250/4:3/576/432/5552a19e91cc8d741eb8a93d214586a5/3E45C59B657B0CCC9968C34E0B8689AC/clickandride_Anmeldung-Bild-4.jpg)",156,"{\"canonical_url\":\"https://www.dbinfrago.com/web/schienennetz/leistungen/trassen/trassenbestellung/trassenanmeldung/click_and_ride-10907236\",\"normalized_sha256\":\"8d41ec8cb8e71bddb957af0f0b485d4120af7639a8996a6ff0c2021d1619e916\",\"page\":null,\"source_id\":\"src_87a0d1da7ffe15350d9d\",\"source_sha256\":\"a564b36a60a9e35982e72efd9cc2532b4b6399e780ae1be060c0104a5bf66e09\",\"source_version_id\":\"sv_2e22d860175ac7f66366cbe9\"}","c8c1ce20e76d248c1b9f9046182ef3028370069263e275e478494424ef4366ee"],["chunk_052d1a3976564e3ac72888a2","wiki/sources/click-ride.md",3,"Inhalt","![](https://www.dbinfrago.com/resource/image/10907248/4:3/576/432/43b5b601eace13b79dbac6ccc816b69e/D078C5C715CF6D34B3605F1539D5C48C/clickandride_Anmeldung-Bild-5.jpg)\r\n\r\n- Sie sind registriert und können sich bei unserer Web-App Click&Ride anmelden. Gehen Sie einfach auf [clickandride.dbinfrago.com](https://clickandride.dbinfrago.com/ \"Wird in einem neuen Tab geöffnet\") und geben Sie hier Ihren Benutzernamen sowie das vorher definierte Passwort ein.\r\n- Fertig. Jetzt können Sie direkt starten und innerhalb von 3 Minuten Ihre Strecke buchen.\r\n\r\n**4\\. Kann ich auch selbst User anlegen?**\r\n\r\nJa, dies ist im Kundenportal als Administrator:in ohne Probleme möglich.\r\n\r\nUnsere Empfehlung:Jedes Eisenbahnverkehrsunternehmen sollte mindestens eine:n Administrator:in haben. Wenn Sie Administrator:in in Ihrem Unternehmen werden möchten, schreiben Sie uns einfach eine kurze Mail an: [kundenportal.dbinfrago@deutschebahn.com](mailto:kundenportal.dbinfrago@deutschebahn.com \"Wird in einem neuen Tab geöffnet\") Bitte geben Sie hier Ihre E-Mail Adresse sowie Ihre Kundennummer(n) an.\r\n\r\n**5\\. Warum funktioniert mein Passwort nicht mehr?**\r\n\r\nAktuell ist Ihr Passwort immer 3 Monate gültig. Sollte Ihr Passwort abgelaufen sein, können Sie es im [Kundenportal](https://portal.mynet.service.deutschebahn.com/ \"Wird in einem neuen Tab geöffnet\") der DB InfraGO AG ganz unkompliziert ändern.\r\n\r\n**6\\. Wer ist mein erster Ansprechpartner?**\r\n\r\nIhr erster Ansprechpartner ist Ihr:e Kundenberater:in in Ihrer Region. Sollten Sie noch keine Kontaktdaten haben, nutzen Sie gerne [unsere Kontaktseite](https://www.dbinfrago.com/web/Ihr-Kontakt-zum-Schienennetz-11212488).\r\n\r\n**7\\. An wen wende ich mich bei fehlerhaften Trassen?**",183,"{\"canonical_url\":\"https://www.dbinfrago.com/web/schienennetz/leistungen/trassen/trassenbestellung/trassenanmeldung/click_and_ride-10907236\",\"normalized_sha256\":\"8d41ec8cb8e71bddb957af0f0b485d4120af7639a8996a6ff0c2021d1619e916\",\"page\":null,\"source_id\":\"src_87a0d1da7ffe15350d9d\",\"source_sha256\":\"a564b36a60a9e35982e72efd9cc2532b4b6399e780ae1be060c0104a5bf66e09\",\"source_version_id\":\"sv_2e22d860175ac7f66366cbe9\"}","2fa0d79893734b04b19dd2281504f3b7d02d5a96034e9cfefb67e664fae6e665"],["chunk_26af7fd1643856a8c4599c36","wiki/sources/click-ride.md",4,"Inhalt","Bitte wenden Sie sich bei fehlerhaften Trassen mit einer Dokumentation Ihres Problems via Screenshots an den technischen Support der Anwendung DevOps-Team. Sie erreichen das Team über [next-support@deutschebahn.com](mailto:next-support@deutschebahn.com)\r\n\r\n**8\\. Warum finde ich die Anwendung nicht im Google PlayStore oder im App-Store?**\r\n\r\nEs handelt sich bei Click&Ride nicht um eine klassische App, sondern um eine Web-App, die man wie eine Website einfach als URL in dem Browser eingibt. Bitte nutzen Sie dazu den Browser Google Chrome.\r\n\r\n**FAQs zur Technik**\r\n\r\n**1\\. Warum finde ich mein Triebfahrzeug nicht in der Auswahlliste?**\r\n\r\nDie Bezeichnungen der Triebfahrzeuge auf unserer Auswahlliste sind mehr und mehr an das System des Fahrzeugeinstellungsregisters angelehnt. Sie folgen einem klaren Schema, das wir hier für Sie aufgelistet haben. So können Sie einfach die richtige Bezeichnung und damit Ihr Triebfahrzeug in der Auswahlliste finden.\r\n\r\n- XX YYYY.Z\r\n- XX: Zweistelliger UIC-Ländercode\r\n- YYYY: Vierstellige Baureihennummer\r\n- Z: Baureihenvariantennummer\r\n\r\n**Übrigens**: Eine komplette Übersicht aller Triebfahrzeuge und ihre Bezeichnungen sowie die entsprechenden Grenzlastdaten finden Sie bei uns auf [GretA](https://www.dbinfrago.com/greta \"Wird in einem neuen Tab geöffnet\").\r\n\r\n**2\\. Wo sehe ich meine Buchungen und wie kann ich sie ändern oder stornieren?**\r\n\r\nTrassenbuchungen, die Sie über Click&Ride vorgenommen haben, werden Ihnen an gewohnter Stelle angezeigt: im TPN oder dem Programm, das sie für die EVU-Schnittstelle nutzen. Hier können Sie auch einfach Trassenänderungen oder Stornierungen vornehmen. Mit unserer Web App Click&Ride sind nur Neuanmeldungen von Trassen möglich.\r\n\r\n**3\\. Wie kann ich einen Richtungswechsel bestellen?**",235,"{\"canonical_url\":\"https://www.dbinfrago.com/web/schienennetz/leistungen/trassen/trassenbestellung/trassenanmeldung/click_and_ride-10907236\",\"normalized_sha256\":\"8d41ec8cb8e71bddb957af0f0b485d4120af7639a8996a6ff0c2021d1619e916\",\"page\":null,\"source_id\":\"src_87a0d1da7ffe15350d9d\",\"source_sha256\":\"a564b36a60a9e35982e72efd9cc2532b4b6399e780ae1be060c0104a5bf66e09\",\"source_version_id\":\"sv_2e22d860175ac7f66366cbe9\"}","8dcb176f33e6cad96d39a15f00b341fab18072e3362d9304a76c9aebad034670"],["chunk_494d596ed462179ee7a46053","wiki/sources/click-ride.md",5,"Inhalt","Ein erforderlicher Richtungswechsel kann in Click&Ride bestellt werden, in dem in einem bestellten Via-Punkt der Haltegrund „Richtungswechsel“ ausgewählt wird.\r\n\r\nEin Richtungswechsel wird weiterhin automatisch eingefügt, insofern erforderlich, wenn der Haken „Richtungswechsel erlauben“ gesetzt ist. In der Voreinstellung ist der Haken immer gesetzt.\r\n\r\n**4\\. Wieso benötige ich eine Einzelgrenzlastberechnung für eine Fahrt, die ich schon mehrfach bestellt habe?**\r\n\r\nLeider liegen uns nicht für alle Triebfahrzeuge die entsprechenden Grenzlastdaten vor. Auch können wir bei der automatischen Konstruktion nicht eine Vergleichsbaureihe zur Prüfung heranziehen, wie das bei der manuellen Konstruktion möglich ist.\r\n\r\nEventuell ist Ihr Triebfahrzeug aber schon mit anderem Namen und den entsprechenden Grenzlastdaten bei uns gelistet. Eine komplette Übersicht über alle Triebfahrzeuge und ihre Bezeichnungen sowie die entsprechenden Grenzlastdaten finden Sie bei uns auf [GretA](https://www.dbinfrago.com/greta \"Wird in einem neuen Tab geöffnet\").",130,"{\"canonical_url\":\"https://www.dbinfrago.com/web/schienennetz/leistungen/trassen/trassenbestellung/trassenanmeldung/click_and_ride-10907236\",\"normalized_sha256\":\"8d41ec8cb8e71bddb957af0f0b485d4120af7639a8996a6ff0c2021d1619e916\",\"page\":null,\"source_id\":\"src_87a0d1da7ffe15350d9d\",\"source_sha256\":\"a564b36a60a9e35982e72efd9cc2532b4b6399e780ae1be060c0104a5bf66e09\",\"source_version_id\":\"sv_2e22d860175ac7f66366cbe9\"}","13150598b2fdf0be485d65bd557cd278c356a951838737582e48a55ba71e59a8"],["chunk_7a9665ed1ab3e225be5dd85b","wiki/sources/clickandride-tpn-infoflyer-data.md",0,"Seite 1","TPN und Click&Ride auf einen Blick: Ihr\r\n\r\nWegweiser zur automatischen\r\n\r\nTrassenkonstruktion\r\n\r\nUnser Ziel:\r\n\r\nWir möchten Qualität und Geschwindigkeit bei der Fahrplanerstellung für alle Beteiligten steigern.\r\n\r\nUnser Weg:\r\n\r\nErhöhung des Anteils der direkt automatisch erstellten Trassen.\r\n\r\nUnser Tipp:\r\n\r\nNutzen Sie unsere Hinweise auf der folgenden Seite und wenden Sie sich bei Fragen gern an uns.\r\n\r\nAutomatische Konstruktion: Sie können nur gewinnen!\r\n\r\nSie gewinnen wertvolle Zeit – durch erheblich reduzierte Wartezeit zwischen Trassenbestellung\r\n\r\nund Erhalt des Trassenangebotes.\r\n\r\nÜber Click&Ride können Sie flexibel und unverbindlich genau die Trasse finden, die zur Ihren\r\n\r\nWünschen passt – das Ganze ohne Wartezeit und interaktiv über eine moderne\r\n\r\nWeboberfläche.\r\n\r\nIst meine Trasse automatisch konstruierbar?\r\n\r\nZug verkehrt als kurzfristiger X Zug verkehrt in Abschnitten außerhalb des Schienen-\r\n\r\nGelegenheitsverkehr netzes der DB InfraGO AG (außer ausgewählte Infrastrukturen\r\n\r\nwie z. B. Hamburger Hafen)\r\n\r\nAbfahrt innerhalb der nächsten 7 X BZA und/oder EGB erforderlich\r\n\r\nKalendertage (Click&Ride)\r\n\r\nGefahrguttransport X 20h-Züge\r\n\r\nZüge mit KV-Profil X Besetzter Schienenpersonenverkehr\r\n\r\nUngebundene Leerreisezüge\r\n\r\nKeine aufwendige Bearbeitung\r\n\r\nClick&Ride oder automatische Konstruktion TPN?\r\n\r\nClick&Ride Automatische Konstruktion TPN\r\n\r\nSie möchten mit wenigen Klicks Ihre Trasse bestellen, Sie nutzen in Ihrem Unternehmen bereits TPN oder\r\n\r\nauch von unterwegs, z. B. mit Smartphone oder Tablet. die EVU-Schnittstelle\r\n\r\nSie möchten ein unverbindliches Trassenangebot Sie möchten nicht noch ein weiteres IT-Programm /\r\n\r\ninnerhalb von 3 Minuten erhalten. Tool nutzen.\r\n\r\nSie möchten den Fahrplan vor der Buchung noch Ihre Bestellung wird direkt an die automatische",230,"{\"canonical_url\":null,\"normalized_sha256\":\"82d26b73e204325d7d39756adf1e9a92b595c6bc3ec677e568b479425adb19dd\",\"page\":1,\"source_id\":\"src_a12e612bd58a0ba3aa61\",\"source_sha256\":\"3a46c895ee9f6ae7dfedbee6b96550d08620c45f1e2bdc013398dae7af5e4f0b\",\"source_version_id\":\"sv_b65369e50e48687c06b48afd\"}","8afa650b3c714c2c00069c1e1a96ee353d89fde3d6bfbdf3cbfbe9b6ff473b22"],["chunk_1584261baced0df0e67ad4a3","wiki/sources/clickandride-tpn-infoflyer-data.md",1,"Seite 1","einmal ansehen. Konstruktion weitergeleitet, sofern sie plausibel ist.\r\n\r\nSie möchten Ihre Trassenanfrage vor Annahme des Wir möchten allerdings darauf hinweisen, dass bei\r\n\r\nTrassenangebots beliebig oft überarbeiten können, Auffälligkeiten in der Plausibilisierung der Bestellz. B. durch Laufwegveränderungen. angaben unsere Trassenkonstrukteure Ihre Angaben -\r\n\r\nIhr Zug steht zur Abfahrt bereit und soll in Kürze nach Rücksprache - anpassen und Ihre Bestellung\r\n\r\nabfahren. (mind. 45 Minuten) erneut an die automatische Konstruktion geben\r\n\r\nwerden, wodurch der Bestellprozess verlängert wird.\r\n\r\nKontakt:\r\n\r\nhttps://fahrweg.dbinfrago.com/fahrweg-de/kontaktformular-9738464#",77,"{\"canonical_url\":null,\"normalized_sha256\":\"82d26b73e204325d7d39756adf1e9a92b595c6bc3ec677e568b479425adb19dd\",\"page\":1,\"source_id\":\"src_a12e612bd58a0ba3aa61\",\"source_sha256\":\"3a46c895ee9f6ae7dfedbee6b96550d08620c45f1e2bdc013398dae7af5e4f0b\",\"source_version_id\":\"sv_b65369e50e48687c06b48afd\"}","3992854531f71d2d79d87495d03114fc41261db08f26b1a6bf9a80937435d00f"],["chunk_95df3fe7f53fd0ac0bad1d76","wiki/sources/clickandride-tpn-infoflyer-data.md",2,"Seite 2","Ihre Checkliste für die automatische Konstruktion mit TPN\r\n\r\nSie haben keine Angaben im Kommentarfeld „Bemerkung Kunde an Netz“ gemacht\r\n\r\nNutzen Sie das Kommentarfeld „Kunde an Netz“ ausschließlich bei aufwendigen Bearbeitungen und speziellen\r\n\r\nSonderwünschen im Rahmen der Konstruktion.\r\n\r\nBitte verzichten Sie im Kommentarfeld auf jegliche Angaben, z. B. zu:\r\n\r\nLaufweg Baureihe Kontaktdaten von Ansprechpartnern\r\n\r\nFalls Sie sich nicht sicher sind, in welches Eingabefeld Sie eine Information aus dem Kommentarfeld eingeben\r\n\r\nkönnen, dann wenden Sie sich gern an Ihren Kundenbetreuer.\r\n\r\nSie haben den genauen Bahnhofsteil ausgewählt (v. a. bei großen Bahnhöfen)\r\n\r\nIn großen Bahnhöfen, z. B. Erfurt, Mainz-Bischofsheim oder Halle, gibt es mehrere Bahnhofsteile.\r\n\r\nBei TPN-Bestellung nur mit der Angabe UE, FMB oder LH ist sowohl eine manuelle als auch eine\r\n\r\nautomatische Trassenkonstruktion erst nach Zuordnung eines Bahnhofsteils möglich.\r\n\r\nSie haben bei Zügen mit LZB mindestens 56 Bremshundertstel angegeben\r\n\r\nDamit ein Zug LZB nutzen darf, muss er mindestens diesen Wert aufweisen.\r\n\r\nZüge mit weniger als 56 Bremshundertstel dürfen nicht mit LZB bestellt werden.\r\n\r\nSie haben bei einer Fahrt mit angehängten Wagen sowohl Wagenzuglänge\r\n\r\nals auch Wagenzuglast angegeben\r\n\r\nWenn Sie bei Zugbestellungen eine Wagenzuglänge größer 0 Meter angeben, muss auch eine Wagenzuglast\r\n\r\n(Gewicht) angegeben werden.\r\n\r\nSie haben bei Verkehrshalten die Mindesthaltezeit beachtet\r\n\r\nDie Mindesthaltezeit für Kundenhalte im Güterverkehr (z. B. für Personalwechsel etc.) beträgt 2 Minuten.\r\n\r\nFür Richtungswechsel sind bei Tfz-Fahrten mindestens 5 Minuten, ansonsten mindestens 30 Minuten zu bestellen.\r\n\r\nSie haben die korrekte Zuggattung angegeben",233,"{\"canonical_url\":null,\"normalized_sha256\":\"82d26b73e204325d7d39756adf1e9a92b595c6bc3ec677e568b479425adb19dd\",\"page\":2,\"source_id\":\"src_a12e612bd58a0ba3aa61\",\"source_sha256\":\"3a46c895ee9f6ae7dfedbee6b96550d08620c45f1e2bdc013398dae7af5e4f0b\",\"source_version_id\":\"sv_b65369e50e48687c06b48afd\"}","ebdd8bfc409fdb53dfd1f33ebbfbd35a98c4fd7ae25d5c277a6699f18db1078a"],["chunk_30e2cbe7d7a14d60127fce50","wiki/sources/clickandride-tpn-infoflyer-data.md",3,"Seite 2","Ausschließlich Unternummern der Zuggattungen mit Bezug auf Sonder- bzw. Gelegenheitsverkehr sind\r\n\r\nautomatisch konstruierbar.\r\n\r\nEntspricht der automatisiert erstellte Fahrplan nicht Ihren Bestellwünschen? Dann wenden Sie sich\r\n\r\nbitte per E-Mail an die Trassenbestellannahme der Region, in der die Trasse beginnt. Dort können Sie\r\n\r\neine Anpassung veranlassen.\r\n\r\nKontakt:\r\n\r\nRegion Süd: [E-Mail-Adresse entfernt] Region Nord: [E-Mail-Adresse entfernt]\r\n\r\nRegion Südwest: [E-Mail-Adresse entfernt] Region Ost: [E-Mail-Adresse entfernt]\r\n\r\nRegion Mitte: [E-Mail-Adresse entfernt] Region Südost: [E-Mail-Adresse entfernt]\r\n\r\nRegion West: [E-Mail-Adresse entfernt]\r\n\r\nImpressum\r\n\r\nDB InfraGO AG, Adam-Riese-Straße 11–13,\r\n\r\n60327 Frankfurt am Main\r\n\r\nStand: Januar 2024\r\n\r\nÄnderungen vorbehalten, Einzelangaben ohne Gewähr.\r\n\r\nGeltung der SNB/NBS in ihrer jeweils gültigen Fassung\r\n\r\nbleibt unberührt.",101,"{\"canonical_url\":null,\"normalized_sha256\":\"82d26b73e204325d7d39756adf1e9a92b595c6bc3ec677e568b479425adb19dd\",\"page\":2,\"source_id\":\"src_a12e612bd58a0ba3aa61\",\"source_sha256\":\"3a46c895ee9f6ae7dfedbee6b96550d08620c45f1e2bdc013398dae7af5e4f0b\",\"source_version_id\":\"sv_b65369e50e48687c06b48afd\"}","679781a987ff304546583d83df4cd8a2141261fffe0ffd1dbca2f56040f922df"],["chunk_909c1c0b897c4d555078bf32","wiki/sources/code-of-conduct-netzfahrplan-data.md",0,"Seite 1","RTK - Runder Tisch Kapazität\r\n\r\nCode of conduct Netzfahrplan:\r\n\r\nVerhaltenskodex zum kapazitätsoptimierten Bestellverhalten\r\n\r\nRunder Tisch Kapazität | Branchen-Projekt | AG 2| Frankfurt am Main | 16.03.2020",26,"{\"canonical_url\":null,\"normalized_sha256\":\"8c7fc89d6cc0282642e4740caa000d3a73642da60daaca5e9028c8534039a28a\",\"page\":1,\"source_id\":\"src_c5afa20ea56973906da4\",\"source_sha256\":\"3d0b374d1fc6e56ea3c13a99524ac6f09f9ee5304577300702bd4a78c61c2578\",\"source_version_id\":\"sv_eb5996835007d62cfc7ee534\"}","84bf14164a629793481ffed89baba992d96bcaba227e6a62818d312c49369010"],["chunk_193a6629d2f34b3dbadc3472","wiki/sources/code-of-conduct-netzfahrplan-data.md",1,"Seite 2","Code of conduct Netzfahrplan: Verhaltenskodex\r\n\r\nzum kapazitätsoptimierten Bestellverhalten\r\n\r\nGemeinsam tragen wir als Zugangsberechtigte bei der Trassenanmeldung durch\r\n\r\nunser Bestellverhalten dazu bei, dass die kostbare Kapazität auf dem Schienennetz\r\n\r\nder Bundesrepublik Deutschland optimal für das Wachstum auf der Schiene genutzt\r\n\r\nwerden kann.\r\n\r\nFolgenden Verhaltenskodex legen wir dabei zugrunde:\r\n\r\n Wir wählen den optimalen Bestellzeitpunkt (Netzfahrplan, 2.Netzfahrplanperiode,\r\n\r\nunterjährig im Netzfahrplan. Gelegenheitsverkehr).\r\n\r\n Wir vermeiden Doppelbestellungen. Wenn das unvermeidbar ist, machen wir es\r\n\r\ntransparent.\r\n\r\n Wir bestellen das, was wir fahren wollen. Wir bestellen nicht taktisch.\r\n\r\n Nicht benötigte Trassen bestellen wir unmittelbar nach Bekanntwerden der\r\n\r\nNichtnutzung ab. Das gilt insbesondere nach Bekanntgabe des endgültigen Netzfahrplans.\r\n\r\n Wir nehmen an der Fahrlagenberatung teil. Gesprächswünschen verschließen wir uns\r\n\r\nnicht. Auch an von anderen Zugangsberechtigten initiierten Konfliktlösungsgesprächen\r\n\r\nnehmen wir teil.\r\n\r\n2 RTK | 16.03.2020",129,"{\"canonical_url\":null,\"normalized_sha256\":\"8c7fc89d6cc0282642e4740caa000d3a73642da60daaca5e9028c8534039a28a\",\"page\":2,\"source_id\":\"src_c5afa20ea56973906da4\",\"source_sha256\":\"3d0b374d1fc6e56ea3c13a99524ac6f09f9ee5304577300702bd4a78c61c2578\",\"source_version_id\":\"sv_eb5996835007d62cfc7ee534\"}","49c5f21c63b32f7351dba1fc6e6d58097ee8fb276e665a28e484a97522105b6e"],["chunk_da4f43a9125fa9ff1ee1c91f","wiki/sources/code-of-conduct-netzfahrplan-data.md",2,"Seite 3","Code of conduct Netzfahrplan: Verhaltenskodex zum\r\n\r\nkapazitätsoptimierten Verhalten für die DB InfraGO AG\r\n\r\nWir als DB InfraGO AG tragen dazu bei, dass die kostbare Kapazität auf\r\n\r\ndem Schienennetz der Bundesrepublik Deutschland optimal für das Wachstum auf\r\n\r\nder Schiene genutzt werden kann.\r\n\r\nFolgenden Verhaltenskodex legen wir dabei für uns zugrunde:\r\n\r\n Wir zeigen bei Koordinierungsverfahren die Zeitlinie und die dazugehörige Schrittfolge\r\n\r\nauf.\r\n\r\n Wir benennen nach Freigabe der Offenlegung der relevanten Geschäftsgeheimnisse\r\n\r\nunverzüglich die konfliktbehafteten Parteien.\r\n\r\n Wir zeigen für jeden Konflikt alternative Lösungsmöglichkeiten – soweit vorhanden –\r\n\r\nauf.\r\n\r\n Wir unterrichten nach der Koordinierung und Entscheidung beabsichtigte Ablehnungen\r\n\r\nunverzüglich an die Bundesnetzagentur und ermöglichen so eine kurzfristige\r\n\r\nKommunikation an die Zugangsberechtigten.\r\n\r\n Wir schaffen schrittweise beginnend im Netzfahrplan 2022 Anreize für die\r\n\r\nZugangsberechtigten ihre Trassen zum aus Kapazitätssicht optimalen Bestellzeitpunkt\r\n\r\n(Netzfahrplan, 2.Netzfahrplanperiode, unterjährig im Netzfahrplan. Gelegenheitsverkehr)\r\n\r\nzu bestellen.\r\n\r\n3 RTK | 16.03.2020",142,"{\"canonical_url\":null,\"normalized_sha256\":\"8c7fc89d6cc0282642e4740caa000d3a73642da60daaca5e9028c8534039a28a\",\"page\":3,\"source_id\":\"src_c5afa20ea56973906da4\",\"source_sha256\":\"3d0b374d1fc6e56ea3c13a99524ac6f09f9ee5304577300702bd4a78c61c2578\",\"source_version_id\":\"sv_eb5996835007d62cfc7ee534\"}","9a8b1d9163b71de72ed5d163c9cbbe4c88882ddd712855a1e6668a84476bc4b4"],["chunk_03b44018829e7dd5155845bc","wiki/sources/download-taf-tap-glossar-data.md",0,"Seite 1","Glossar mit den wesentlichen Begriffen aus TAF/TAP TSI\r\n\r\nStand Dezember 2023 - dieses Dokument wird laufend aktualisiert und online bereitgestellt\r\n\r\nViele weitere Begriffe werden zudem im Glossar der TAF TSI und der TAP TSI erklärt (sowohl in Deutsch als auch Englisch) - an dieser Stelle beschränken wir uns\r\n\r\nauf einen Auszug - die deutschen Verordnungen finden Sie auch auf unserer Internetseite im Kapitel 3:\r\n\r\nhttps://www.dbinfrago.com/taf-tap-tsi\r\n\r\nBegriff Beschreibung\r\n\r\nBDV Betriebsdatenverteiler. Datenschnittstelle des Betriebs der DB InfraGO AG, die sich gemäß den\r\n\r\nSpezifikationen eines Common Interface verhält\r\n\r\nCI (Common Interface) Die Abkürzung für das \"Common Interface\", also die technische Schnittstelle, die sowohl für die\r\n\r\nDatenübertragung im Betrieb als auch in der Trassenanmeldung erforderlich ist. Neben den\r\n\r\nSchnittstellen existieren allerdings auch Webanwendungen, die eine eigene Schnittstelle ersetzen (z.B.\r\n\r\ndas neue Bestellportal für Trassenanmeldungen)\r\n\r\nCompany Code Eindeutiger Code zur Identifikation eines Unternehmens, welches am Datenaustausch mit TAF/TAP\r\n\r\nteilnimmt. Zwingende Voraussetzung für alle beteiligten Unternehmen. Beantragung erfolgt derzeit\r\n\r\nbei der UIC, ab 2026 erfolgt die Beantragung für alle Akteure innerhalb der EU bei der ERA. Für\r\n\r\nweitere Details s. bereits veröffentlichter Flyer\r\n\r\nERA Die ERA ist die European Union Agency of Railways mit dem Mandat: \"The EU Agency for Railways is\r\n\r\nmandated to issue single safety certificates and vehicle (type) authorisations valid in multiple\r\n\r\nEuropean countries and to ensure an interoperable European Rail Traffic Management System, in the\r\n\r\ndevelopment and implementation of the Single European Railway Area.\" (zitiert von der ERA-\r\n\r\nHomepage)",237,"{\"canonical_url\":null,\"normalized_sha256\":\"daa4d8e870f689a51764d980e10aa769e347a381d3d4a1cc30e57d7898bfd51e\",\"page\":1,\"source_id\":\"src_660bf8039cf0527ee7b6\",\"source_sha256\":\"51fb412fc4f0d41650cb55bfbd30199f90cdff881090b1f2af568d45ea8636e2\",\"source_version_id\":\"sv_51fb412fc4f0d41650cb55bf\"}","bfbe2c96cb79fbdd9133266f78f17fb518e48a161ad7d0770df8999221eaa392"],["chunk_230476f029d841c4cf950a5d","wiki/sources/download-taf-tap-glossar-data.md",1,"Seite 1","Die ERA ist zudem für den Organisation Code verantwortlich (und grundsätzlich auch für den Company\r\n\r\nCode)\r\n\r\nIM Die englische Bezeichnung für ein EIU (Eisenbahninfrastrukturunternehmen), also ein \"Infrastructure\r\n\r\nManager\"\r\n\r\nJSG JSG steht für die \"Joint Sector Group\". Die \"TAF and TAP TSI RU/IM Joint Sector Group\" wurde 2012\r\n\r\nals eine freiwillige Organisation gegründet, um die Einführung der TAF TSI zu begleiten. Seit 2014 ist\r\n\r\nauch die TAP TSI hier aufgenommen. Primär bereitet die JSG Positionen des Sektors für das TAF/TAP\r\n\r\nSteering Committee vor, koordiniert Change Requests und unterstützt den Einführungsprozess der\r\n\r\nERA\r\n\r\nLeadRU, auch LRU Das federführende EVU einer Verkehrsleistung. In der TAF/TAP ist kein Datenaustausch zwischen\r\n\r\ndiesem EVU und dem EIU vorgesehen, außer es ist in einem Trassenabschnitt gleichzeitig auch\r\n\r\nResponsibleRU. Es kann sein, dass ein und dasselbe EVU die Rollen des LeadRU, RA und ResponsibleRU\r\n\r\neinnimmt\r\n\r\nNAE Die National Allocation Entity ist eine Rolle, die durch die TAF/TAP TSI definiert ist und innerhalb eines\r\n\r\nLandes für die eindeutige und einheitliche Vergabe von Location Codes (Primary und Subsidiary\r\n\r\nLocation Codes) verantwortlich ist. Die Location Codes werden von der NAE in einer eindeutigen Liste\r\n\r\nverwaltet. In Deutschland ist die DB InfraGO AG von den Behörden mit der Durchführung dieser Rolle\r\n\r\nbetraut worden.\r\n\r\nNBN Die Nutzungsbedingungen Netz - also die Vertragsgrundlage zur Nutzung von Trassen im Schienennetz\r\n\r\nder DB InfraGO AG - Nachfolger der SNB\r\n\r\nNCP Die Abkürzung steht für National Contact Point. Der National Contact Point fungiert im Auftrag des\r\n\r\nBundesministeriums für Digitales und Verkehr (BMDV) als nationale Anlaufstelle für den Deutschen",251,"{\"canonical_url\":null,\"normalized_sha256\":\"daa4d8e870f689a51764d980e10aa769e347a381d3d4a1cc30e57d7898bfd51e\",\"page\":1,\"source_id\":\"src_660bf8039cf0527ee7b6\",\"source_sha256\":\"51fb412fc4f0d41650cb55bfbd30199f90cdff881090b1f2af568d45ea8636e2\",\"source_version_id\":\"sv_51fb412fc4f0d41650cb55bf\"}","ebfaea98e9fe9343c34da98d5913cfa014800372a6600b11ca5a7e490e403e89"],["chunk_e00e5a9144c94aa2cf224841","wiki/sources/download-taf-tap-glossar-data.md",2,"Seite 1","Bahnsektor zur Umsetzung von TAF/TAP TSI und ist bei der DB InfraGO AG ansässig. Dabei nimmt er\r\n\r\ndie Interessenvertretung des EU-Mitgliedstaates Deutschland in den europäischen TAF/TAP Gremien\r\n\r\nwahr. Beschrieben sind die Aufgaben des NCP auch in den EU-Verordnungen zu TAF/TAP TSI.\r\n\r\nObjectInfo TAF/TAP-Meldung im betrieblichen Datenaustausch, welche Angaben zu TrainAcitvities enthält. Sie\r\n\r\nwird vom EVU an das EIU geschickt und beinhaltet aktuelle Informationen zu Anschluss- oder\r\n\r\nUmlaufverknüpfungen zwischen Zügen. Einführung ist für 09/2023 geplant\r\n\r\nOperations Der Bereich von TAF/TAP, der sich primär mit dem laufenden Betrieb beschäftigt. Die Bereiche\r\n\r\n\"Operations\" und \"Planning\" sind die beiden fachlichen Säulen von TAF/TAP\r\n\r\nOTN Operational Train Number (betriebliche Zugnummer). Entspricht in ihrer Funktion auf dem Gebiet der\r\n\r\nDB InfraGO der heutigen Zugnummer.\r\n\r\nPath Trasse. Objekt im Kontext des TAF/TAP-Modells. Also die Kapazität, der \"Slot\", auf dem der Zug fährt.\r\n\r\nWird durch eine PathID identifiziert\r\n\r\nPDM bzw. Path Details Abkürzung für die Path Details Message, eine Pflichtnachricht in der Trassenanmeldung und eine\r\n\r\nebenfalls im Betrieb genutzte Nachricht. Diese Nachricht wird vom EIU an die EVU geschickt\r\n\r\nPlanning Der Bereich von TAF/TAP, der sich primär mit Trassenanmeldungen und dem Fahrplan beschäftigt. Die\r\n\r\nBereiche \"Operations\" und \"Planning\" sind die beiden fachlichen Säulen von TAF/TAP\r\n\r\nGlossar zu TAF/TAP TSI, Stand Dezember 2023 Seite 1 von 3",208,"{\"canonical_url\":null,\"normalized_sha256\":\"daa4d8e870f689a51764d980e10aa769e347a381d3d4a1cc30e57d7898bfd51e\",\"page\":1,\"source_id\":\"src_660bf8039cf0527ee7b6\",\"source_sha256\":\"51fb412fc4f0d41650cb55bfbd30199f90cdff881090b1f2af568d45ea8636e2\",\"source_version_id\":\"sv_51fb412fc4f0d41650cb55bf\"}","68d593d057dd33389fd32c85fcb478f95882a4fea00560edcd23278441c47fe0"],["chunk_6dfa6ab185d7b13bde7c1fcc","wiki/sources/download-taf-tap-glossar-data.md",3,"Seite 2","Begriff Beschreibung\r\n\r\nPLC Diese Abkürzung steht für Primary Location Code. Mit dem Primary Location Code werden\r\n\r\nBetriebsstellen eindeutig und in einem einheitlichen, standardisierten europäischen Format codiert.\r\n\r\nSomit identifiziert ein Primary Location Code eine Örtlichkeit auf dem Schienennetzwerk. Primary\r\n\r\nLocation Codes werden zukünftig bei jeder Art von TAF/TAP-Kommunikation verwendet. Daneben\r\n\r\nwird es auch weiterhin die Ril100 Codes geben (z.B. im Trassenbestellsystem).\r\n\r\nPrimary Location Eine Primary Location ist ein Ort innerhalb des Schienennetzes, an dem eine Zugfahrt beginnt, endet,\r\n\r\nanhält, durchfährt oder die Strecke wechselt. Dieser Ort muss von einem Infrastrukturbetreiber, der\r\n\r\ndurch einen Company Code identifiziert wird, verwaltet werden. Beispiele für Primary Locations sind\r\n\r\nBahnhöfe, Haltepunkte oder Grenzpunkte.\r\n\r\nPRM bzw. Path Request Abkürzung für die Path Request Message, eine Pflichtnachricht in der Trassenanmeldung, mit der ein\r\n\r\nPath erstmalig bestellt wird. Diese Nachricht wird vom EVU an das EIU geschickt\r\n\r\nRA Die Abkürzung für den \"Responsible Applicant\", das vertragsbindende Unternehmen. Es kann sein,\r\n\r\ndass ein und dasselbe EVU die Rollen des LeadRU, RA und ResponsibleRU einnimmt.\r\n\r\nReferenceTrain Familie von Zügen (Trains) bzw. Zugfamilie. Objekt im Kontext des TAF/TAP-Modells. Darunter werden\r\n\r\nverschiedene zueinander gehörige Züge (Trains) zusammengefasst. Dies können z.B. Züge mit\r\n\r\nabweichenden Zugläufen werktags und am Wochenende sein. Wird durch eine ReferenceTrainID\r\n\r\nidentifiziert\r\n\r\nResponsibleIM Das für die Bereitstellung einer Trasse (Path) und die betriebliche Durchführung der Zugfahrt auf\r\n\r\nInfrastrukturseite verantwortliche EIU. Analog zum ResponsibleRU.",222,"{\"canonical_url\":null,\"normalized_sha256\":\"daa4d8e870f689a51764d980e10aa769e347a381d3d4a1cc30e57d7898bfd51e\",\"page\":2,\"source_id\":\"src_660bf8039cf0527ee7b6\",\"source_sha256\":\"51fb412fc4f0d41650cb55bfbd30199f90cdff881090b1f2af568d45ea8636e2\",\"source_version_id\":\"sv_51fb412fc4f0d41650cb55bf\"}","b2773faca825eba224bc4dda0fecde0e5ca300d969c8085fd3d3bc275a7e87da"],["chunk_691eecbef550448fc3f31beb","wiki/sources/download-taf-tap-glossar-data.md",4,"Seite 2","ResponsibleRU, auch RRU Das für die Durchführung einer Zugfahrt verantwortliche EVU, also der \"Eigner der Trasse\". Dieses EVU\r\n\r\nist gemäß TAF/TAP der Partner für den Datenaustausch mit dem EIU in der Betriebsphase. Dies behält\r\n\r\nauch seine Gültigkeit, falls das ResponsibleRU einen Subunternehmer mit der Durchführung der\r\n\r\nZugfahrt beauftragt. Es kann sein, dass ein und dasselbe EVU die Rollen des LeadRU, RA und\r\n\r\nResponsibleRU einnimmt.\r\n\r\nRNE RNE ist die Rail Net Europe, ein europäischer Verband der Eisenbahninfrastrukturunternehmen. Sie ist\r\n\r\neiner der Hauptakteure bei der Umsetzung von TAF/TAP TSI. Die RNE gibt es seit 2004 und hat zum\r\n\r\nübergreifenden Ziel die Herausforderungen des europäischen Eisenbahnsektors anzugehen und zu\r\n\r\nvereinfachen. Die RNE versucht, die europäische Vernetzung seiner Mitglieder zu unterstützen und z.B.\r\n\r\nauch bei rechtlichen Fragestellungen innerhalb der EU zu vermitteln. Mit Stand 2022 hat die RNE 38\r\n\r\nVollmitglieder aus über 30 Ländern.\r\n\r\nRoute Objekt im Kontext des TAF/TAP-Modells. Beinhaltet den groben Zuglauf (Start, Ziel, Grenzübergänge\r\n\r\nsowie Informationen zu Tageswechseln) durch Europa.\r\n\r\nWird durch eine RouteID identifiziert\r\n\r\nRU Die englische Bezeichnung für ein EVU (Eisenbahnverkehrsunternehmen), also ein \"Railway\r\n\r\nUndertaking\"\r\n\r\nSLC Ein Subsidiary Location Code identifiziert eindeutig eine Subsidiary Location innerhalb einer\r\n\r\nbestehenden Primary Location. Mit dem SLC werden Subsidiary Locations in einem einheitlichen,\r\n\r\nstandardisierten europäischen Format codiert. Mit Hilfe der Subsidiary Location Codes kann ein\r\n\r\nNachrichtenaustausch zwischen Unternehmen stattfinden, die in einer geschäftlichen Beziehung\r\n\r\nstehen.\r\n\r\nSubsidiary Location Eine Subsidiary Location ist immer mit einer Primary Location verknüpft und beschreibt Teile,",237,"{\"canonical_url\":null,\"normalized_sha256\":\"daa4d8e870f689a51764d980e10aa769e347a381d3d4a1cc30e57d7898bfd51e\",\"page\":2,\"source_id\":\"src_660bf8039cf0527ee7b6\",\"source_sha256\":\"51fb412fc4f0d41650cb55bfbd30199f90cdff881090b1f2af568d45ea8636e2\",\"source_version_id\":\"sv_51fb412fc4f0d41650cb55bf\"}","6ad1b77340cbbb64f9c59095157320e8a87b6f65378b68b54566cb4302da9460"],["chunk_f4c2966b7573656c83d6ee68","wiki/sources/download-taf-tap-glossar-data.md",5,"Seite 2","Attribute von Primary Locations oder die Verwendung von Primary Locations näher. Es kann sich auch\r\n\r\num einen nicht-schienengebundenen oder schienengebundenen Punkt handeln, der nicht von einem\r\n\r\nInfrastrukturbetreiber (IM) betrieben wird. Beispiele für Subsidiary Locations sind Gleise, Tankanlagen\r\n\r\noder Ladepunkte.\r\n\r\nTAF TSI Telematics Applications for Freight Services - Technical Specification for Interoperability (Telematische\r\n\r\nAnwendungen für den Güterverkehr - Technische Spezifikation für Interoperabilität)\r\n\r\nTAP TSI Telematics Applications for Passenger Services - Technical Specification for Interoperability\r\n\r\n(Telematische Anwendungen für den Personenverkehr - Technische Spezifikation für Interoperabilität)\r\n\r\nTCM/PTCM Train Composition Message (Güterverkehr) bzw. Passenger Train Composition Message\r\n\r\n(Personenverkehr): Die beiden künftig verbindlichen Nachrichtentypen von TAF/TAP im Betrieb\r\n\r\nwerden vom EVU an das EIU gesendet. Sie geben Auskunft über die aktuellen Zuginhaltsdaten (Länge,\r\n\r\nGewicht, Angaben zu Bremsen, etc.) und sind nicht gleichzusetzen mit der heutigen Wagenliste.\r\n\r\nEinführung erfolgt vsl. in 09/2023, eine Verpflichtung zu Abgabe in NBN ist grundsätzlich geplant -\r\n\r\ngenauere Termine hierzu werden separat kommuniziert, sobald bekannt.\r\n\r\nTPN Trassen Portal Netz, also das bisherige System zur Trassenanmeldung bei der DB InfraGO. Dieses wird\r\n\r\nmit Einführung von TAF/TAP durch das neue Bestellsystem ersetzt. Aus heutiger Sicht bleibt TPN bis\r\n\r\neinschließlich Fahrplanjahr 2025 führend, ab Fahrplanjahr 2026 gilt das neue System\r\n\r\nTrain Zug. Objekt im Kontext des TAF/TAP-Modells. Beinhaltet Informationen zum Zug und dessen\r\n\r\nEigenschaften. Wird durch eine TrainID identifiziert.\r\n\r\nGlossar zu TAF/TAP TSI, Stand Dezember 2023 Seite 2 von 3",226,"{\"canonical_url\":null,\"normalized_sha256\":\"daa4d8e870f689a51764d980e10aa769e347a381d3d4a1cc30e57d7898bfd51e\",\"page\":2,\"source_id\":\"src_660bf8039cf0527ee7b6\",\"source_sha256\":\"51fb412fc4f0d41650cb55bfbd30199f90cdff881090b1f2af568d45ea8636e2\",\"source_version_id\":\"sv_51fb412fc4f0d41650cb55bf\"}","f32b15911d72bd0f7aa87a0526042c697a1908e12a6d6841ab7f40df1e828c5d"],["chunk_f8dc47de8f9f289558f4aa3a","wiki/sources/download-taf-tap-glossar-data.md",6,"Seite 3","Begriff Beschreibung\r\n\r\nTrain Activity Ein Feld innerhalb einiger Nachrichten, u.a. in der Trassenanmeldung für den Fahrplan oder der\r\n\r\nInformation zu Abhängigkeiten zwischen Zügen im Betrieb. Hiermit wird die Zugaktivität an einem\r\n\r\nbestimmten Laufwegspunkt beschrieben. Dies sind z.B. gebräuchliche Aktivitäten wie der\r\n\r\nVerkehrshalt, Anschluss-/Umlaufinformationen oder das Zusammenführen von Zügen oder weniger\r\n\r\noft genutzte wie Lokführererholungshalt, Fotohalt etc.\r\n\r\nUIC Die International Union of Railways mit der Mission: \"Promote rail transport globally with the\r\n\r\nobjective of responding effectively to current and future challenges relating to mobility and\r\n\r\nsustainable development; Develop and facilitate all forms of international cooperation among\r\n\r\nmembers and promote sharing of best practice\" (Auszug zitiert von der UIC-Homepage). Die UIC\r\n\r\nvergibt u.a. die Company Codes\r\n\r\nUIC-Telegramme Bestehendes international standardisiertes Datenaustauschformat im Betrieb. Einige Telegramme sind\r\n\r\nanalog zu den entsprechenden TAF/TAP-Meldungen (z.B. Zugstandort, Prognose). Gegenüber den\r\n\r\nTAF/TAP-Meldungen decken die UIC-Telegramme jedoch weniger Geschäftsfälle ab und bieten\r\n\r\nweniger Umfang\r\n\r\nxsd XML Schema Definition: Das Dateiformat, in dem z.B. die RNE ihre Schnittstellenbeschreibungen\r\n\r\nveröffentlicht\r\n\r\nZugnummer Die heute im Betrieb verwandte Zugnummer, mit der auch Passagiere im Aushangfahrplan ihren Zug\r\n\r\nerkennen können\r\n\r\nGlossar zu TAF/TAP TSI, Stand Dezember 2023 Seite 3 von 3",188,"{\"canonical_url\":null,\"normalized_sha256\":\"daa4d8e870f689a51764d980e10aa769e347a381d3d4a1cc30e57d7898bfd51e\",\"page\":3,\"source_id\":\"src_660bf8039cf0527ee7b6\",\"source_sha256\":\"51fb412fc4f0d41650cb55bfbd30199f90cdff881090b1f2af568d45ea8636e2\",\"source_version_id\":\"sv_51fb412fc4f0d41650cb55bf\"}","458d76a4c10481f2b76f1de5bce7f735b39b8e0c6f12975d073419534732b310"]]');
